QT_ISI(24,{"4090":["(Maka siapakah) artinya, tiada seorang pun (yang lebih aniaya daripada orang yang membuat-buat dusta terhadap Allah) dengan cara menisbatkan kepada-Nya mempunyai sekutu dan anak (dan mendustakan kebenaran) Alquran (ketika datang kepadanya. Bukankah di neraka Jahanam tersedia tempat tinggal) yakni tempat menetap (bagi orang-orang yang kafir?) tentu saja disediakan.",[["۞ فَمَنْ","Kemudian siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّن","daripada (seorang) yang"],["كَذَبَ","pembohongan"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["وَكَذَّبَ","dan menafikan"],["بِٱلصِّدْقِ","kebenaran"],["إِذْ","apabila"],["جَآءَهُۥٓ ۚ","ia datang kepadanya"],["أَلَيْسَ","Adakah (ada) tidak"],["فِى","dalam"],["جَهَنَّمَ","Neraka"],["مَثْوًۭى","sebuah tempat tinggal"],["لِّلْكَـٰفِرِينَ","bagi orang-orang kafir"]]],"4091":["(Dan orang yang membawa kebenaran) yaitu Nabi saw. (dan membenarkannya) orang-orang mukmin. Lafal Al-Ladzii di sini bermakna Al-Ladziina, yakni jamak (mereka itulah orang-orang yang bertakwa) maksudnya, yang menghindarkan diri dari kemusyrikan.",[["وَٱلَّذِى","Dan orang yang"],["جَآءَ","dibawa"],["بِٱلصِّدْقِ","kebenaran"],["وَصَدَّقَ","dan beriman"],["بِهِۦٓ ۙ","di dalamnya"],["أُو۟لَـٰٓئِكَ","mereka"],["هُمُ","[mereka]"],["ٱلْمُتَّقُونَ","(adalah) orang-orang yang soleh"]]],"4092":["(Mereka memperoleh apa yang mereka kehendaki pada sisi Rabb mereka. Demikianlah balasan orang-orang yang berbuat baik) untuk diri mereka sendiri, berkat keimanan mereka.",[["لَهُم","Untuk mereka"],["مَّا","(ialah) apa"],["يَشَآءُونَ","mereka mahu"],["عِندَ","dengan"],["رَبِّهِمْ ۚ","Tuhan mereka"],["ذَٰلِكَ","Itu"],["جَزَآءُ","(ialah) pahala"],["ٱلْمُحْسِنِينَ","(dari) orang-orang yang berbuat baik"]]],"4093":["(Agar Allah menutupi mengampuni bagi mereka perbuatan buruk yang mereka kerjakan dan membalas mereka dengan upah yang baik dari apa yang telah mereka kerjakan) lafal Aswa-a dan Ahsana bermakna As-Sayyi dan Al-Hasan.",[["لِيُكَفِّرَ","Bahawa Allah akan hapuskan"],["ٱللَّهُ","Bahawa Allah akan hapuskan"],["عَنْهُمْ","daripada mereka"],["أَسْوَأَ","(yang) paling teruk"],["ٱلَّذِى","apa"],["عَمِلُوا۟","mereka lakukan"],["وَيَجْزِيَهُمْ","dan memberi ganjaran kepada mereka"],["أَجْرَهُم","hak mereka"],["بِأَحْسَنِ","untuk (yang) terbaik"],["ٱلَّذِى","apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"4094":["(Bukankah Allah cukup untuk melindungi hamba-Nya) yakni Nabi saw. tentu saja, (Dan mereka mempertakuti kamu) khithab ini ditujukan kepada Nabi saw. sendiri (dengan sesembahan-sesembahan yang selain Allah) yakni, berhala-berhala; maksud mereka, bahwa berhala-berhala itu akan membunuhnya atau akan membuatnya cacat. (Dan siapa yang disesatkan Allah maka tidak seorang pun pemberi petunjuk baginya.)",[["أَلَيْسَ","bukan"],["ٱللَّهُ","Allah"],["بِكَافٍ","mencukupi"],["عَبْدَهُۥ ۖ","(untuk) hamba-Nya"],["وَيُخَوِّفُونَكَ","Dan mereka mengancam kamu"],["بِٱلَّذِينَ","dengan mereka"],["مِن","selain Dia"],["دُونِهِۦ ۚ","selain Dia"],["وَمَن","Dan sesiapa"],["يُضْلِلِ","Allah biarkan sesat"],["ٱللَّهُ","Allah biarkan sesat"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِنْ","sebarang"],["هَادٍۢ","panduan"]]],"4095":["(Dan barang siapa yang diberi petunjuk oleh Allah, maka tidak seorang pun yang dapat menyesatkannya. Bukankah Allah Maha Perkasa) Maha Menang atas semua perkara-Nya (lagi mempunyai pembalasan) terhadap musuh-musuh-Nya. Tentu benar.",[["وَمَن","Dan sesiapa"],["يَهْدِ","Allah memberi petunjuk"],["ٱللَّهُ","Allah memberi petunjuk"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِن","sebarang"],["مُّضِلٍّ ۗ","yang mengelirukan"],["أَلَيْسَ","bukan"],["ٱللَّهُ","Allah"],["بِعَزِيزٍۢ","Maha Perkasa"],["ذِى","Maha Berkuasa membalas"],["ٱنتِقَامٍۢ","Maha Berkuasa membalas"]]],"4096":["(Dan sungguh jika) huruf Lam bermakna qasam (kamu tanyakan kepada mereka, \"Siapakah yang menciptakan langit dan bumi?\" Niscaya mereka menjawab, \"Allah.\" Katakanlah, \"Maka terangkanlah kepadaku tentang apa yang kalian seru) yang kalian sembah (selain Allah) yakni berhala-berhala (jika Allah hendak mendatangkan kemudaratan kepadaku, apakah berhala-berhala kalian itu dapat menghilangkan kemudaratan itu) tentu saja tidak (atau jika Allah hendak memberi rahmat kepadaku, apakah mereka dapat menahan rahmat-Nya?) tentu saja tidak pula. Menurut suatu qiraat dibaca Kaasyifaati Dhurrihii dan Mumsikaati rahmatihii (Katakanlah, \"Cukuplah Allah bagiku. Kepada-Nyalah bertawakkal orang-orang yang berserah diri\") yaitu orang-orang yang percaya hanya kepada-Nya.",[["وَلَئِن","Dan jika"],["سَأَلْتَهُم","kamu bertanya kepada mereka"],["مَّنْ","yang"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["لَيَقُولُنَّ","Pasti, mereka akan berkata"],["ٱللَّهُ ۚ","Allah"],["قُلْ","Katakanlah"],["أَفَرَءَيْتُم","Kemudian adakah kamu melihat"],["مَّا","apa"],["تَدْعُونَ","kamu menyeru"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["إِنْ","jika"],["أَرَادَنِىَ","Allah takdirkan untuk aku"],["ٱللَّهُ","Allah takdirkan untuk aku"],["بِضُرٍّ","kemudaratan"],["هَلْ","adalah"],["هُنَّ","mereka"],["كَـٰشِفَـٰتُ","penyingkiran"],["ضُرِّهِۦٓ","(dari) bahaya (dari)Nya"],["أَوْ","atau"],["أَرَادَنِى","jika Dia berniat untukku"],["بِرَحْمَةٍ","belas kasihan"],["هَلْ","adalah"],["هُنَّ","mereka"],["مُمْسِكَـٰتُ","penahan"],["رَحْمَتِهِۦ ۚ","(dari) rahmat-Nya"],["قُلْ","Katakanlah"],["حَسْبِىَ","Cukuplah Allah bagiku"],["ٱللَّهُ ۖ","Cukuplah Allah bagiku"],["عَلَيْهِ","atas Dia"],["يَتَوَكَّلُ","letak amanah"],["ٱلْمُتَوَكِّلُونَ","mereka yang amanah"]]],"4097":["(Katakanlah, \"Hai kaumku, bekerjalah sesuai dengan keadaan kalian) kondisi kalian (sesungguhnya aku akan bekerja pula) sesuai dengan keadaanku (maka kelak kalian akan mengetahui)",[["قُلْ","Katakanlah"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْمَلُوا۟","Kerja"],["عَلَىٰ","(mengikut) kepada"],["مَكَانَتِكُمْ","kedudukan kamu"],["إِنِّى","sesungguhnya, aku"],["عَـٰمِلٌۭ ۖ","bekerja"],["فَسَوْفَ","kemudian tidak lama lagi"],["تَعْلَمُونَ","kamu akan tahu"]]],"4098":["(siapa) lafal Man adalah Isim Maushul (yang akan mendapat siksa yang menghinakannya dan lagi ditimpa) yakni ia ditimpa (oleh azab yang kekal\") yang abadi, yaitu azab neraka; dan sungguh Allah telah menghinakan mereka di dalam perang Badar.",[["مَن","(Ke atas) siapa"],["يَأْتِيهِ","akan datang"],["عَذَابٌۭ","azab"],["يُخْزِيهِ","memalukan dia"],["وَيَحِلُّ","dan turun"],["عَلَيْهِ","pada dia"],["عَذَابٌۭ","azab"],["مُّقِيمٌ","kekal abadi"]]],"4099":["(Sesungguhnya Kami menurunkan kepadamu Alkitab untuk manusia dengan membawa kebenaran) lafal Bil haqqi berta'alluq kepada lafal Anzalnaa (siapa yang mendapat petunjuk maka untuk dirinya sendiri) yakni hidayahnya itu untuk dirinya sendiri (dan siapa yang sesat maka sesungguhnya dia semata-mata sesat buat kerugian dirinya sendiri, dan kamu sekali-kali bukanlah orang yang bertanggung jawab terhadap mereka) lalu karenanya kamu dapat memaksa mereka untuk menerima hidayah.",[["إِنَّآ","Sesungguhnya Kami"],["أَنزَلْنَا","Kami mendedahkan"],["عَلَيْكَ","kepada kamu"],["ٱلْكِتَـٰبَ","Kitab"],["لِلنَّاسِ","untuk manusia"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["فَمَنِ","Jadi sesiapa"],["ٱهْتَدَىٰ","menerima hidayah"],["فَلِنَفْسِهِۦ ۖ","maka (itu) untuk jiwanya"],["وَمَن","dan sesiapa"],["ضَلَّ","sesat"],["فَإِنَّمَا","kemudian sahaja"],["يَضِلُّ","dia sesat"],["عَلَيْهَا ۖ","terhadap (jiwanya)"],["وَمَآ","Dan tidak"],["أَنتَ","kamu"],["عَلَيْهِم","(berada) atas mereka"],["بِوَكِيلٍ","seorang pengurus"]]],"4100":["(Allah mematikan jiwa orang ketika matinya dan) memegang (jiwa orang yang belum mati di waktu tidurnya) artinya Allah memegangnya di waktu ia tidur (maka Dia tahan jiwa orang yang telah Dia tetapkan kematiannya dan melepaskan jiwa yang lain sampai waktu yang ditentukan) bagi kematiannya. Jiwa yang dilepaskan itu hanyalah dimatikan perasaannya saja, tetapi ia masih hidup, berbeda dengan jiwa yang benar-benar dimatikan. (Sesungguhnya pada yang demikian itu) pada hal-hal yang telah disebutkan itu (terdapat tanda-tanda) yang menunjukkan akan kekuasaan Allah (bagi kaum yang berpikir) maka karenanya mereka mengetahui, bahwa yang berkuasa melakukan hal tersebut berkuasa pula untuk membangkitkannya; dan orang-orang kafir Quraisy tidak memikirkan hal ini.",[["ٱللَّهُ","Allah"],["يَتَوَفَّى","mengambil"],["ٱلْأَنفُسَ","jiwa-jiwa"],["حِينَ","(pada) masa"],["مَوْتِهَا","(dari) kematian mereka"],["وَٱلَّتِى","dan orang yang"],["لَمْ","tidak"],["تَمُتْ","mati"],["فِى","dalam"],["مَنَامِهَا ۖ","tidur mereka"],["فَيُمْسِكُ","Kemudian Dia menyimpan"],["ٱلَّتِى","orang yang"],["قَضَىٰ","Dia telah menetapkan"],["عَلَيْهَا","bagi mereka"],["ٱلْمَوْتَ","kematian itu"],["وَيُرْسِلُ","dan menghantar"],["ٱلْأُخْرَىٰٓ","yang lain"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّى ۚ","ditentukan"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَتَفَكَّرُونَ","yang merenung"]]],"4101":["(Bahkan) tetapi (mereka mengambil selain Allah) yaitu berhala-berhala sebagai tuhan-tuhan (pemberi syafaat) di hadapan Allah nanti, menurut dugaan mereka. (Katakanlah) kepada mereka, (\"Apakah) mereka dapat memberikan syafaat (meskipun mereka tidak memiliki sesuatu pun) daripada syafaat itu dan tidak memiliki hal-hal lainnya pula (dan tidak berakal\") yakni, kalian hanya menyembah mereka tidak ada alasan lain, hal ini tentu saja tidak patut bagi kalian.",[["أَمِ","Atau"],["ٱتَّخَذُوا۟","adakah mereka telah mengambil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["شُفَعَآءَ ۚ","pemberi syafaat"],["قُلْ","Katakanlah"],["أَوَلَوْ","walaupun"],["كَانُوا۟","mereka adalah"],["لَا","tidak"],["يَمْلِكُونَ","memiliki"],["شَيْـًۭٔا","sesuatu"],["وَلَا","dan bukan"],["يَعْقِلُونَ","mereka faham"]]],"4102":["(Katakanlah, \"Hanya kepunyaan Allahlah syafaat itu semua) maksudnya, syafaat itu khusus bagi Dia, maka tiada seorang pun yang dapat memberikannya melainkan dengan seizin Dia. (Kepunyaan-Nya kerajaan langit dan bumi. Kemudian kepada-Nya pulalah kalian dikembalikan.\")",[["قُل","Katakanlah"],["لِّلَّهِ","Kepunyaan Allah (kepunyaan)"],["ٱلشَّفَـٰعَةُ","syafaat itu"],["جَمِيعًۭا ۖ","semua"],["لَّهُۥ","Untuk Dia"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["ثُمَّ","Kemudian"],["إِلَيْهِ","kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"4103":["(Dan apabila disebutkan nama Allah semata) tanpa menyebut nama tuhan-tuhan mereka kesal) mendongkol dan anti pati (hati orang-orang yang tidak beriman kepada kehidupan akhirat, dan apabila nama-nama sembahan-sembahan selain Allah yang disebut) yakni berhala-berhala (tiba-tiba mereka bergirang hati.)",[["وَإِذَا","Dan apabila"],["ذُكِرَ","Allah disebut"],["ٱللَّهُ","Allah disebut"],["وَحْدَهُ","bersendirian"],["ٱشْمَأَزَّتْ","mengecut dengan keengganan"],["قُلُوبُ","(the) hati"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ ۖ","di akhirat"],["وَإِذَا","dan apabila"],["ذُكِرَ","disebut"],["ٱلَّذِينَ","mereka"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["إِذَا","lihatlah"],["هُمْ","mereka"],["يَسْتَبْشِرُونَ","bergembiralah"]]],"4104":["(Katakanlah, \"Wahai Allah) lafal Allaahumma maknanya sama dengan Yaa Allah (Pencipta langit dan bumi) yakni yang mengadakan keduanya (Yang mengetahui barang yang gaib dan yang nyata) yakni apa-apa yang gaib dan apa-apa yang nyata dapat disaksikan (Engkaulah Yang memutuskan antara hamba-hamba-Mu tentang apa yang selalu mereka perselisihkan\") mengenai masalah agama, berilah aku petunjuk kepada yang benar dari apa yang mereka perselisihkan.",[["قُلِ","Katakanlah"],["ٱللَّهُمَّ","Ya Allah"],["فَاطِرَ","Pencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["عَـٰلِمَ","Maha Mengetahui"],["ٱلْغَيْبِ","(dari) perkara ghaib"],["وَٱلشَّهَـٰدَةِ","dan yang disaksikan"],["أَنتَ","kamu"],["تَحْكُمُ","akan menilai"],["بَيْنَ","antara"],["عِبَادِكَ","hambamu"],["فِى","dalam"],["مَا","apa"],["كَانُوا۟","mereka dahulu"],["فِيهِ","di dalamnya"],["يَخْتَلِفُونَ","berbeza"]]],"4105":["(Dan sekiranya orang-orang yang zalim mempunyai apa yang ada di bumi semuanya dan -ada pula- sebanyak itu besertanya, niscaya mereka akan menebus dirinya dengan itu dari siksa yang buruk pada hari kiamat. Dan jelaslah) tampaklah dengan jelas (bagi mereka azab Allah yang belum pernah mereka perkirakan) yang tidak pernah mereka duga.",[["وَلَوْ","Dan jika"],["أَنَّ","Dan jika"],["لِلَّذِينَ","orang yang"],["ظَلَمُوا۟","buat salah"],["مَا","(mempunyai) apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا","semua"],["وَمِثْلَهُۥ","dan (yang) seumpamanya"],["مَعَهُۥ","dengannya"],["لَٱفْتَدَوْا۟","mereka akan menebus"],["بِهِۦ","dengannya"],["مِن","daripada"],["سُوٓءِ","(yang) jahat"],["ٱلْعَذَابِ","(dari) hukuman itu"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۚ","Kiamat"],["وَبَدَا","Dan (akan) muncul"],["لَهُم","kepada mereka"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَمْ","tidak"],["يَكُونُوا۟","mereka telah"],["يَحْتَسِبُونَ","diambil kira"]]],"4106":["(Dan jelaslah bagi mereka akibat buruk dari apa yang telah mereka perbuat dan menimpa) mengenai (kepada mereka apa yang mereka dahulu selalu memperolok-olokkannya) yakni azab.",[["وَبَدَا","Dan akan menjadi jelas"],["لَهُمْ","kepada mereka"],["سَيِّـَٔاتُ","(yang) kejahatan"],["مَا","apa"],["كَسَبُوا۟","mereka perolehi"],["وَحَاقَ","dan akan mengelilingi"],["بِهِم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["بِهِۦ","[di dalamnya]"],["يَسْتَهْزِءُونَ","mengejek"]]],"4107":["(Maka apabila manusia ditimpa) yang dimaksud adalah jenis manusia (bahaya ia menyeru Kami, kemudian apabila Kami berikan kepadanya) Kami anugerahkan kepadanya (nikmat) yakni pemberian nikmat (dari Kami ia berkata, \"Sesungguhnya aku diberi nikmat itu hanyalah atas sepengetahuan) dari Allah bahwasanya aku adalah orang yang pantas untuk mendapatkannya.\" Atau dengan kata lain, karena kepintaranku. (Sebenarnya itu) maksudnya, ucapan itu (adalah ujian) cobaan yang ditimpakan kepada seorang hamba (tetapi kebanyakan mereka itu tidak mengetahui) bahwasanya pemberian nikmat itu merupakan Istidraj dan ujian baginya.",[["فَإِذَا","Maka apabila"],["مَسَّ","sentuhan"],["ٱلْإِنسَـٰنَ","lelaki itu"],["ضُرٌّۭ","kesusahan"],["دَعَانَا","dia menyeru Kami"],["ثُمَّ","kemudian"],["إِذَا","apabila"],["خَوَّلْنَـٰهُ","Kami kurniakan (kepada) dia"],["نِعْمَةًۭ","suatu nikmat"],["مِّنَّا","daripada Kami"],["قَالَ","katanya"],["إِنَّمَآ","Hanya"],["أُوتِيتُهُۥ","Aku telah diberikannya"],["عَلَىٰ","bagi"],["عِلْمٍۭ ۚ","pengetahuan"],["بَلْ","Bahkan"],["هِىَ","ia"],["فِتْنَةٌۭ","(adalah) percubaan"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"4108":["(Sungguh orang-orang yang sebelum mereka juga mengatakan itu pula) yakni umat-umat sebelum mereka, seperti apa yang telah dikatakan oleh Qarun dan kaumnya yang mengatakan hal yang serupa (maka tiadalah berguna bagi mereka apa yang dahulu mereka usahakan.)",[["قَدْ","Sesungguhnya"],["قَالَهَا","berkata ia"],["ٱلَّذِينَ","mereka"],["مِن","sebelum mereka"],["قَبْلِهِمْ","sebelum mereka"],["فَمَآ","tetapi (tidak)"],["أَغْنَىٰ","manfaat"],["عَنْهُم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["يَكْسِبُونَ","peroleh"]]],"4109":["(Maka mereka ditimpa oleh akibat buruk dari apa yang mereka usahakan) yakni menerima pembalasannya. (Dan orang-orang yang lalim di antara mereka) yakni orang-orang Quraisy (akan ditimpa akibat buruk dari usahanya dan mereka tidak dapat melepaskan diri) dari azab Kami; maka Kami timpakan kepada mereka paceklik selama tujuh tahun, sesudah itu mereka dimudahkan lagi rezekinya.",[["فَأَصَابَهُمْ","Kemudian memukul mereka"],["سَيِّـَٔاتُ","(yang) kejahatan"],["مَا","apa"],["كَسَبُوا۟ ۚ","mereka perolehi"],["وَٱلَّذِينَ","Dan orang yang"],["ظَلَمُوا۟","telah melakukan kesalahan"],["مِنْ","daripada"],["هَـٰٓؤُلَآءِ","ini"],["سَيُصِيبُهُمْ","akan menyerang mereka"],["سَيِّـَٔاتُ","(yang) kejahatan"],["مَا","apa"],["كَسَبُوا۟","mereka perolehi"],["وَمَا","dan bukan"],["هُم","mereka"],["بِمُعْجِزِينَ","akan dapat melarikan diri"]]],"4110":["(Dan tidakkah mereka mengetahui bahwa Allah melapangkan rezeki) meluaskannya (bagi siapa yang dikehendaki-Nya) sebagai ujian baginya (dan menyempitkannya?) membatasinya bagi siapa yang dikehendaki-Nya sebagai cobaan baginya. (Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan Allah bagi kaum yang beriman) kepada-Nya.",[["أَوَلَمْ","Jangan"],["يَعْلَمُوٓا۟","mereka tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يَبْسُطُ","memanjang"],["ٱلرِّزْقَ","rezeki itu"],["لِمَن","untuk siapa"],["يَشَآءُ","Dia kehendaki"],["وَيَقْدِرُ ۚ","dan menyekat"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"4111":["(Katakanlah, \"Hai hamba-hamba-Ku yang melampaui batas terhadap diri mereka sendiri, janganlah kalian berputus asa) dapat dibaca Laa Taqnithuu atau Laa Taqnathuu; sebagian ahli qiraat ada yang membacanya Laa Taqnuthuu; artinya janganlah kalian putus asa (dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa semuanya) bagi orang yang bertobat dari kemusyrikan. (Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang.)",[["۞ قُلْ","Katakanlah"],["يَـٰعِبَادِىَ","Wahai hamba-Ku"],["ٱلَّذِينَ","Orang yang"],["أَسْرَفُوا۟","telah melanggar"],["عَلَىٰٓ","terhadap"],["أَنفُسِهِمْ","diri mereka"],["لَا","jangan"],["تَقْنَطُوا۟","putus asa"],["مِن","daripada"],["رَّحْمَةِ","(the) Rahmat"],["ٱللَّهِ ۚ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَغْفِرُ","memaafkan"],["ٱلذُّنُوبَ","dosa-dosa"],["جَمِيعًا ۚ","semua"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","Dia"],["ٱلْغَفُورُ","(ialah) Yang Maha Pengampun"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"4112":["(Dan kembalilah kalian) bertobatlah kalian (kepada Rabb kalian, dan berserah dirilah) ikhlaskanlah di dalam beramal (kepada-Nya sebelum datang kepada kalian azab kemudian kalian tidak dapat ditolong lagi) yakni azab itu tidak dapat dicegah jika kalian tidak bertobat kepada-Nya.",[["وَأَنِيبُوٓا۟","Dan berpaling"],["إِلَىٰ","kepada"],["رَبِّكُمْ","Tuhanmu"],["وَأَسْلِمُوا۟","dan serahkan"],["لَهُۥ","kepada-Nya"],["مِن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَأْتِيَكُمُ","datang kepada kamu"],["ٱلْعَذَابُ","azab"],["ثُمَّ","kemudian"],["لَا","tidak"],["تُنصَرُونَ","kamu akan dibantu"]]],"4113":["(Dan ikutilah sebaik-baik apa yang diturunkan kepada kalian dari Rabb kalian) yaitu Alquran (sebelum datang azab kepada kalian dengan tiba-tiba, sedang kalian tidak menyadari) akan kedatangannya.",[["وَٱتَّبِعُوٓا۟","Dan ikut"],["أَحْسَنَ","(yang) terbaik"],["مَآ","apa"],["أُنزِلَ","didedahkan"],["إِلَيْكُم","kepada kamu"],["مِّن","daripada"],["رَّبِّكُم","Tuhanmu"],["مِّن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَأْتِيَكُمُ","datang kepada kamu"],["ٱلْعَذَابُ","azab"],["بَغْتَةًۭ","tiba-tiba"],["وَأَنتُمْ","sedangkan kamu"],["لَا","jangan"],["تَشْعُرُونَ","mempersepsikan"]]],"4114":["Maka bersegeralah kalian sebelum tiba waktunya (seseorang mengatakan, \"Alangkah menyesalnya aku) lafal Yaa Hasrataa pada asalnya adalah Yaa Hasratii, artinya amat menyesallah aku (atas kelalaianku terhadap Allah) yaitu karena tidak taat kepada-Nya (dan sesungguhnya) lafal In adalah bentuk Takhfif dari Inna, asalnya Innii yakni sesungguhnya aku (aku adalah termasuk orang-orang yang benar-benar memperolok-olokan\") agama-Nya dan Kitab-Nya.",[["أَن","Jangan-jangan"],["تَقُولَ","patut cakap"],["نَفْسٌۭ","sebuah jiwa"],["يَـٰحَسْرَتَىٰ","Oh! penyesalan aku"],["عَلَىٰ","atas"],["مَا","apa"],["فَرَّطتُ","aku abaikan"],["فِى","dalam"],["جَنۢبِ","mengambil kira (kepada)"],["ٱللَّهِ","Allah"],["وَإِن","dan bahawa"],["كُنتُ","aku pernah"],["لَمِنَ","pasti, antara"],["ٱلسَّـٰخِرِينَ","yang mengejek"]]],"4115":["(Atau datang saatnya seseorang berkata, \"Kalau sekiranya Allah memberi petunjuk kepadaku) untuk mengerjakan ketaatan sehingga aku mendapat petunjuk (tentulah aku termasuk orang-orang yang bertakwa\") yakni orang-orang yang takut akan azab-Nya.",[["أَوْ","Atau"],["تَقُولَ","ia sepatutnya berkata"],["لَوْ","Jika itu"],["أَنَّ","Jika itu"],["ٱللَّهَ","Allah"],["هَدَىٰنِى","(telah) membimbing aku"],["لَكُنتُ","pasti, aku (akan) telah"],["مِنَ","antara"],["ٱلْمُتَّقِينَ","orang yang soleh"]]],"4116":["(Atau datang saatnya seseorang berkata ketika ia melihat azab, \"Kalau sekiranya aku dapat kembali) ke dunia (niscaya aku akan termasuk orang-orang yang berbuat baik.\") yakni, orang-orang yang beriman. Maka, dikatakan kepada mereka oleh Allah swt.:",[["أَوْ","Atau"],["تَقُولَ","ia sepatutnya berkata"],["حِينَ","apabila"],["تَرَى","ia melihat"],["ٱلْعَذَابَ","azab"],["لَوْ","Jika"],["أَنَّ","sahaja"],["لِى","untuk aku"],["كَرَّةًۭ","peluang lagi"],["فَأَكُونَ","maka aku boleh jadi"],["مِنَ","antara"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"4117":["(\"Benar, sesungguhnya telah datang ayat-ayat-Ku kepadamu) yakni, Alquran yang dapat memberikan hidayah kepadamu (lalu kamu mendustakannya dan kamu menyombongkan diri) yaitu tidak mau beriman kepada ayat-ayat-Ku (dan adalah kamu termasuk orang-orang yang kafir.\")",[["بَلَىٰ","ya"],["قَدْ","sesungguhnya"],["جَآءَتْكَ","datang kepada kamu"],["ءَايَـٰتِى","Ayat-ayat Aku"],["فَكَذَّبْتَ","tetapi kamu menafikan"],["بِهَا","mereka"],["وَٱسْتَكْبَرْتَ","dan bersikap sombong"],["وَكُنتَ","dan kamu adalah"],["مِنَ","antara"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"4118":["(Dan pada hari kiamat kamu akan melihat orang-orang yang berbuat dusta terhadap Allah) yaitu mereka yang menisbatkan sekutu dan anak kepada-Nya (mukanya menjadi hitam. Bukankah dalam neraka Jahanam itu ada tempat) yakni tempat tinggal (bagi orang-orang yang menyombongkan diri?) artinya, tidak mau beriman; memang benar.",[["وَيَوْمَ","Dan (pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["تَرَى","kamu akan melihat"],["ٱلَّذِينَ","orang yang"],["كَذَبُوا۟","berbohong"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["وُجُوهُهُم","muka mereka"],["مُّسْوَدَّةٌ ۚ","(akan) dihitamkan"],["أَلَيْسَ","Adakah (ada) tidak"],["فِى","dalam"],["جَهَنَّمَ","Neraka"],["مَثْوًۭى","sebuah tempat tinggal"],["لِّلْمُتَكَبِّرِينَ","bagi orang yang sombong"]]],"4119":["(Dan Allah menyelamatkan) dari neraka Jahanam (orang-orang yang bertakwa) orang-orang yang memelihara diri dari kemusyrikan (karena kemenangan mereka) karena mereka memperoleh tempat kemenangan, yaitu surga yang menjadi tempat tinggal mereka (mereka tidak disentuh oleh keburukan dan tidak pula mereka berduka cita.)",[["وَيُنَجِّى","Dan Allah akan menyelamatkan"],["ٱللَّهُ","Dan Allah akan menyelamatkan"],["ٱلَّذِينَ","orang yang"],["ٱتَّقَوْا۟","takut (Dia)"],["بِمَفَازَتِهِمْ","ke tempat keselamatan mereka"],["لَا","tidak"],["يَمَسُّهُمُ","akan menyentuh mereka"],["ٱلسُّوٓءُ","yang jahat"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"4120":["(Allah menciptakan segala sesuatu dan Dia memelihara segala sesuatu) Dia mengatur dan menguasainya menurut apa yang dikehendaki-Nya.",[["ٱللَّهُ","Allah"],["خَـٰلِقُ","(ialah) Pencipta"],["كُلِّ","(dari) semua"],["شَىْءٍۢ ۖ","benda"],["وَهُوَ","dan Dia"],["عَلَىٰ","(sudah) tamat"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["وَكِيلٌۭ","seorang Penjaga"]]],"4121":["(Kepunyaan-Nyalah kunci-kunci perbendaharaan langit dan bumi) yakni berupa air hujan tumbuh-tumbuhan dan lain sebagainya (Dan orang-orang yang kafir terhadap ayat-ayat Allah) yaitu Alquran (mereka itulah orang-orang yang merugi) ayat ini berhubungan langsung dengan firman-Nya, \"Dan Allah menyelamatkan orang-orang yang bertakwa...\" (Q.S. Az-Zumar, 61) dan ayat yang ada di antara keduanya merupakan jumlah I'tiradh atau kalimat sisipan.",[["لَّهُۥ","Untuk Dia"],["مَقَالِيدُ","(adalah) kunci"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۗ","dan bumi"],["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["بِـَٔايَـٰتِ","dalam (the) Ayat"],["ٱللَّهِ","(milik) Allah"],["أُو۟لَـٰٓئِكَ","mereka"],["هُمُ","mereka"],["ٱلْخَـٰسِرُونَ","(adalah) orang-orang yang rugi"]]],"4122":["(Katakanlah, \"Maka apakah kalian menyuruh aku menyembah selain Allah, hai orang-orang yang tidak berpengetahuan?\") lafal Ghaira dinashabkan oleh lafal A'budu yang juga menjadi Ma'mul dari lafal Ta-muruunnii atau Ta-muruunanii dengan memperkirakan adanya huruf An sebelumnya.",[["قُلْ","Katakanlah"],["أَفَغَيْرَ","Adakah (ia) selain daripada"],["ٱللَّهِ","Allah"],["تَأْمُرُوٓنِّىٓ","kamu pesan aku"],["أَعْبُدُ","(untuk) beribadat"],["أَيُّهَا","Wahai"],["ٱلْجَـٰهِلُونَ","yang jahil"]]],"4123":["(Dan sesungguhnya telah diwahyukan kepadamu dan kepada nabi-nabi sebelummu) demi Allah (\"Jika kamu mempersekutukan Allah) hai Muhammad, seumpamanya (niscaya akan hapuslah amalmu dan tentulah kamu termasuk orang-orang yang merugi.)",[["وَلَقَدْ","Dan sesungguhnya"],["أُوحِىَ","ia telah didedahkan"],["إِلَيْكَ","kepada kamu"],["وَإِلَى","dan kepada"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum kamu"],["قَبْلِكَ","(ada) sebelum kamu"],["لَئِنْ","jika"],["أَشْرَكْتَ","kamu mempersekutukan (dengan Allah)"],["لَيَحْبَطَنَّ","pasti, akan menjadi tidak bernilai"],["عَمَلُكَ","perbuatan kamu"],["وَلَتَكُونَنَّ","dan kamu pasti akan menjadi"],["مِنَ","antara"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"4124":["(Karena itu, maka hendaklah Allah) saja (kamu sembah dan hendaklah kamu termasuk orang-orang yang bersyukur\") atas nikmat-Nya kepadamu.",[["بَلِ","Bahkan"],["ٱللَّهَ","Tetapi sembahlah Allah"],["فَٱعْبُدْ","Tetapi sembahlah Allah"],["وَكُن","dan jadilah"],["مِّنَ","antara"],["ٱلشَّـٰكِرِينَ","yang bersyukur"]]],"4125":["(Dan mereka tidak mengagungkan Allah dengan pengagungan yang semestinya) yakni mereka tidak mengenal Allah dengan pengenalan yang sebenarnya; atau, mereka tidak mengagungkan-Nya dengan pengagungan yang sesungguhnya sewaktu mereka menyekutukan-Nya dengan selain-Nya (padahal bumi seluruhnya) lafal ayat ini menjadi Hal dan maksud dari lafal Jamii'an ialah bumi yang berlapis tujuh itu (dalam genggaman kekuasaan-Nya) maksudnya berada di dalam kekuasaan dan tasharuf-Nya (pada hari kiamat dan langit digulung) dilipat menjadi satu (dengan tangan kanan-Nya) yakni dengan kekuasaan-Nya (Maha Suci dan Maha Tinggi Allah dari apa yang mereka persekutukan) bersama-Nya.",[["وَمَا","Dan tidak"],["قَدَرُوا۟","mereka menilai"],["ٱللَّهَ","Allah"],["حَقَّ","(dengan) benar"],["قَدْرِهِۦ","penilaian"],["وَٱلْأَرْضُ","manakala bumi"],["جَمِيعًۭا","sepenuhnya"],["قَبْضَتُهُۥ","(akan) dalam genggaman-Nya"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["وَٱلسَّمَـٰوَٰتُ","dan syurga"],["مَطْوِيَّـٰتٌۢ","(akan) dilipat"],["بِيَمِينِهِۦ ۚ","di Tangan Kanan-Nya"],["سُبْحَـٰنَهُۥ","Maha Suci Dia"],["وَتَعَـٰلَىٰ","Dan Maha Tinggi Dia"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"4126":["(Dan ditiuplah sangkakala) pada tiupan yang pertama (maka matilah) artinya mati mendadaklah (siapa yang di langit dan di bumi kecuali siapa yang dikehendaki Allah) yaitu para bidadari, para pelayan surga dan selain keduanya. (Kemudian ditiup sangkakala itu sekali lagi maka tiba-tiba mereka) yakni semua makhluk yang telah mati itu (berdiri seraya menunggu) apa yang bakal diputuskan terhadap diri mereka.",[["وَنُفِخَ","Dan (akan) ditiup"],["فِى","[dalam]"],["ٱلصُّورِ","sangkakala"],["فَصَعِقَ","maka (akan) jatuh mati"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَن","dan sesiapa"],["فِى","(berada) di atas"],["ٱلْأَرْضِ","bumi"],["إِلَّا","kecuali"],["مَن","yang"],["شَآءَ","Allah berkehendak"],["ٱللَّهُ ۖ","Allah berkehendak"],["ثُمَّ","Kemudian"],["نُفِخَ","(ia akan) ditiup"],["فِيهِ","[di dalamnya]"],["أُخْرَىٰ","kali kedua"],["فَإِذَا","dan lihatlah"],["هُمْ","mereka"],["قِيَامٌۭ","(akan) berdiri"],["يَنظُرُونَ","menunggu"]]],"4127":["(Dan terang-benderanglah bumi) menjadi terang benderanglah ia (dengan Nur Rabbnya) sewaktu Dia menampilkan kekuasaan-Nya untuk memutuskan perkara peradilan di antara makhluk-Nya (dan diberikanlah kitab) yakni buku catatan amal perbuatan untuk menjalani perhitungan (dan didatangkanlah para nabi dan saksi-saksi) yaitu Nabi Muhammad saw. dan umatnya untuk memberikan persaksian, bahwa para rasul benar-benar telah menyampaikan risalah-Nya (dan diberi keputusan di antara mereka dengan hak) yakni secara adil (sedangkan mereka tidak dirugikan) barang sedikit pun.",[["وَأَشْرَقَتِ","Dan (akan) bersinar"],["ٱلْأَرْضُ","bumi"],["بِنُورِ","dengan cahaya"],["رَبِّهَا","(dari) Tuhannya"],["وَوُضِعَ","dan (akan) diletakkan"],["ٱلْكِتَـٰبُ","Rekod tersebut"],["وَجِا۟ىٓءَ","dan (akan) dibawa"],["بِٱلنَّبِيِّـۧنَ","para Nabi"],["وَٱلشُّهَدَآءِ","dan para saksi"],["وَقُضِىَ","dan ia (akan) dihakimi"],["بَيْنَهُم","antara mereka"],["بِٱلْحَقِّ","dalam kebenaran"],["وَهُمْ","dan mereka"],["لَا","tidak akan dizalimi"],["يُظْلَمُونَ","tidak akan dizalimi"]]],"4128":["(Dan disempurnakan bagi tiap-tiap jiwa apa yang telah dikerjakannya) yakni balasannya (dan Dia lebih mengetahui) (apa yang mereka kerjakan) maka Dia tidak membutuhkan saksi lagi.",[["وَوُفِّيَتْ","Dan (akan) dibayar sepenuhnya"],["كُلُّ","setiap"],["نَفْسٍۢ","jiwa"],["مَّا","apa"],["عَمِلَتْ","ia berlaku"],["وَهُوَ","dan Dia"],["أَعْلَمُ","(adalah) Yang Maha Mengetahui"],["بِمَا","tentang apa"],["يَفْعَلُونَ","mereka lakukan"]]],"4129":["(Dan orang-orang kafir dibawa) dengan secara keras dan paksa (ke neraka Jahanam berombong-rombongan) secara bergelombang lagi terpisah-pisah. (Sehingga apabila mereka sampai ke neraka itu dibukakanlah pintu-pintunya) ayat ini menjadi Jawab dari lafal Idzaa (dan berkatalah kepada mereka penjaga-penjaganya, \"Apakah belum pernah datang kepada kalian rasul-rasul di antara kalian yang membacakan kepada kalian ayat-ayat Rabb kalian) yakni Alquran dan kitab-kitab lainnya (dan memperingatkan kepada kalian akan pertemuan dengan hari ini?\" Mereka menjawab, \"Benar telah datang.\" Tetapi telah pasti berlaku ketetapan azab) yakni sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Sesungguhnya akan Aku penuhi neraka Jahanam...\" (Q.S. As-Sajdah, 13) (terhadap orang-orang yang kafir).",[["وَسِيقَ","Dan (akan) dihalau"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["إِلَىٰ","kepada"],["جَهَنَّمَ","Neraka"],["زُمَرًا ۖ","(dalam) kumpulan"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["جَآءُوهَا","mereka mencapainya"],["فُتِحَتْ","(akan) dibuka"],["أَبْوَٰبُهَا","pintu gerbangnya"],["وَقَالَ","dan (akan) berkata"],["لَهُمْ","kepada mereka"],["خَزَنَتُهَآ","penjaganya"],["أَلَمْ","tidak"],["يَأْتِكُمْ","datang kepada kamu"],["رُسُلٌۭ","Utusan"],["مِّنكُمْ","daripada kamu"],["يَتْلُونَ","mengaji"],["عَلَيْكُمْ","kepada kamu"],["ءَايَـٰتِ","(the) Ayat"],["رَبِّكُمْ","Tuhanmu"],["وَيُنذِرُونَكُمْ","dan memberi amaran kepada kamu"],["لِقَآءَ","(daripada) mesyuarat"],["يَوْمِكُمْ","(pada) harimu"],["هَـٰذَا ۚ","ini"],["قَالُوا۟","Mereka (akan) berkata"],["بَلَىٰ","ya"],["وَلَـٰكِنْ","Tetapi"],["حَقَّتْ","telah dibenarkan"],["كَلِمَةُ","(perkataan)."],["ٱلْعَذَابِ","(dari) hukuman"],["عَلَى","terhadap"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"4130":["(Dikatakan kepada mereka, \"Masukilah pintu-pintu Jahanam itu, sedangkan kalian kekal di dalamnya\") yakni kalian telah ditetapkan untuk menjadi penghuni yang abadi. (Maka seburuk-buruk tempat) maksudnya, tempat tinggal (orang-orang yang menyombongkan diri) adalah Jahanam.",[["قِيلَ","Ia akan dikatakan"],["ٱدْخُلُوٓا۟","Masuk"],["أَبْوَٰبَ","(the) pintu gerbang"],["جَهَنَّمَ","(dari) Neraka"],["خَـٰلِدِينَ","(untuk) kekal selama-lamanya"],["فِيهَا ۖ","di dalamnya"],["فَبِئْسَ","dan celaka adalah"],["مَثْوَى","(tempat tinggal)."],["ٱلْمُتَكَبِّرِينَ","(dari) orang yang sombong"]]],"4131":["(Dan orang-orang yang bertakwa kepada Rabbnya dibawa) dengan lemah lembut (ke dalam surga berombong-rombongan pula, sehingga apabila mereka sampai ke surga itu pintu-pintunya telah dibuka) huruf Wau dalam ayat ini menunjukkan makna Hal dengan diperkirakan adanya lafal Qad sesudahnya (dan berkatalah kepada mereka penjaga-penjaganya, \"Kesejahteraan atas kalian, berbahagialah kalian) lafal Thibtum menjadi Hal (maka masukilah surga ini, sedangkan kalian kekal di dalamnya\") telah ditetapkan untuk menjadi penghuni yang abadi di dalamnya. Jawab lafal Idzaa diperkirakan keberadaannya, yakni lalu mereka memasukinya. Dan dibawanya orang-orang yang bertakwa ke dalam surga serta dibukakannya pintu-pintu surga sebelum mereka datang, hal ini sebagai penghormatan buat mereka. Sedangkan digiringnya orang-orang kafir serta dibukakannya pintu-pintu neraka Jahanam sewaktu mereka datang dimaksud sebagai hinaan buat mereka agar panas neraka Jahanam itu dapat dirasakan oleh mereka sebelum memasukinya",[["وَسِيقَ","Dan (akan) dihalau"],["ٱلَّذِينَ","orang yang"],["ٱتَّقَوْا۟","ditakuti"],["رَبَّهُمْ","Tuhan mereka"],["إِلَى","kepada"],["ٱلْجَنَّةِ","Syurga"],["زُمَرًا ۖ","(dalam) kumpulan"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["جَآءُوهَا","mereka mencapainya"],["وَفُتِحَتْ","dan (akan) dibuka"],["أَبْوَٰبُهَا","pintu gerbangnya"],["وَقَالَ","dan (akan) berkata"],["لَهُمْ","kepada mereka"],["خَزَنَتُهَا","penjaganya"],["سَلَـٰمٌ","Salam sejahtera"],["عَلَيْكُمْ","ke atas kamu"],["طِبْتُمْ","kamu telah melakukannya dengan baik"],["فَٱدْخُلُوهَا","jadi masukkannya"],["خَـٰلِدِينَ","(untuk) kekal selama-lamanya"]]],"4132":["(Dan mereka mengucapkan) sewaktu mereka memasukinya; lafal ayat ini diathafkan kepada lafal Dukhuuluhaa yang diperkirakan keberadaannya tadi pada ayat sebelumnya, (\"Segala puji bagi Allah yang telah memenuhi janji-Nya kepada kami) yakni memasukkan kami ke dalam surga (dan telah memberikan kepada kami tempat ini) surga ini (sedangkan kami diperkenankan menempati) menghuni (tempat dalam surga di mana saja kami kehendaki) karena surga itu semuanya bukanlah tempat yang dipilih antara yang satu dengan yang lainnya, karena semuanya indah (maka sebaik-baik balasan bagi orang-orang yang beramal) adalah surga.",[["وَقَالُوا۟","Dan mereka akan berkata"],["ٱلْحَمْدُ","Segala puji"],["لِلَّهِ","bagi Allah"],["ٱلَّذِى","Siapa"],["صَدَقَنَا","telah memenuhi untuk kita"],["وَعْدَهُۥ","janji dia"],["وَأَوْرَثَنَا","dan telah mewarisi kami"],["ٱلْأَرْضَ","bumi"],["نَتَبَوَّأُ","kita boleh settle"],["مِنَ","[dari]"],["ٱلْجَنَّةِ","(dalam) Syurga"],["حَيْثُ","di mana sahaja"],["نَشَآءُ ۖ","kami mahu"],["فَنِعْمَ","Begitu cemerlang"],["أَجْرُ","(ialah) pahala"],["ٱلْعَـٰمِلِينَ","(daripada) pekerja"]]],"4133":["(Dan kamu akan melihat malaikat-malaikat berlingkar) lafal Haaffiina ini menjadi Hal (di sekeliling 'Arasy) yakni dari segala penjurunya (bertasbih) menjadi Hal dari dhamir Haaffiina (seraya memuji Rabb mereka) yaitu sambil mengucapkan kalimah, Subhaanallaah Wa Bihamdihi, artinya, Maha Suci Allah dan Kami memuji kepada-Nya (dan diberi putusan di antara mereka) di antara semua makhluk (dengan hak) dengan adil, maka orang-orang yang beriman dimasukkan ke dalam surga, dan orang-orang kafir dimasukkan ke dalam neraka (dan diucapkan, \"Segala puji bagi Allah, Rabb semesta alam.\") yaitu setelah kedua golongan itu telah selesai pemutusannya, lalu para malaikat mengakhirinya dengan memuji kepada Allah.",[["وَتَرَى","Dan kamu akan melihat"],["ٱلْمَلَـٰٓئِكَةَ","para Malaikat"],["حَآفِّينَ","sekeliling"],["مِنْ","[dari]"],["حَوْلِ","sekeliling"],["ٱلْعَرْشِ","takhta"],["يُسَبِّحُونَ","bertasbih"],["بِحَمْدِ","(yang) pujian"],["رَبِّهِمْ ۖ","(dari) Tuhan mereka"],["وَقُضِىَ","Dan (akan) diadili"],["بَيْنَهُم","antara mereka"],["بِٱلْحَقِّ","dalam kebenaran"],["وَقِيلَ","dan ia akan dikatakan"],["ٱلْحَمْدُ","Segala puji"],["لِلَّهِ","kepada Allah"],["رَبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"4134":["(Haa Miim) hanya Allah saja yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Mim"]]],"4135":["(Diturunkan Kitab ini) yakni Alquran, menjadi Mubtada (dari Allah) Khabar Mubtada (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["تَنزِيلُ","(The) wahyu"],["ٱلْكِتَـٰبِ","Kitab"],["مِنَ","(adalah) daripada"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْعَلِيمِ","yang Maha Mengetahui"]]],"4136":["(Yang mengampuni dosa) orang-orang mukmin (dan menerima tobat) mereka (lagi keras hukuman-Nya) terhadap orang-orang kafir, yaitu Dia mengeraskan azab-Nya terhadap mereka (Yang mempunyai karunia) yakni Pemberi nikmat yang lapang; Dia bersifat demikian selama-lamanya. Dimudhafkannya lafal Ghaafir kepada Adz-Dzanbi, lafal Qaabil kepada At-Taubi, dan lafal Syadiid kepada Al-Iqaabi mengandung makna Takrif sebagaimana lafal terakhir yaitu Dzith Thauli. (Tiada Tuhan selain Dia. Hanya kepada-Nyalah kembali) semua makhluk pasti kembali kepada-Nya.",[["غَافِرِ","(Yang) Pengampun"],["ٱلذَّنۢبِ","(dari) dosa"],["وَقَابِلِ","dan (the) Penerima"],["ٱلتَّوْبِ","(dari) taubat"],["شَدِيدِ","teruk"],["ٱلْعِقَابِ","(dalam) hukuman"],["ذِى","Pemilik (dari) kelimpahan"],["ٱلطَّوْلِ ۖ","Pemilik (dari) kelimpahan"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["إِلَيْهِ","kepada-Nya"],["ٱلْمَصِيرُ","(ialah) pulangan terakhir"]]],"4137":["(Tidak ada yang memperdebatkan tentang ayat-ayat Allah) yakni Alquran (kecuali orang-orang yang kafir) dari kalangan penduduk kota Mekah. (Karena itu janganlah mereka pulang-balik dengan bebas dari suatu kota ke kota yang lain memperdayakan kamu) mereka pulang balik untuk mencari penghidupan dalam keadaan selamat, janganlah hal itu membuatmu teperdaya, karena sesungguhnya akibat dan tempat kembali mereka adalah neraka.",[["مَا","Tidak"],["يُجَـٰدِلُ","pertikaian"],["فِىٓ","tentang"],["ءَايَـٰتِ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["إِلَّا","kecuali"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["فَلَا","jadi (biar) jangan"],["يَغْرُرْكَ","menipu kamu"],["تَقَلُّبُهُمْ","pergerakan mereka"],["فِى","dalam"],["ٱلْبِلَـٰدِ","bandar-bandar"]]],"4138":["(Sebelum mereka, kaum Nuh dan golongan-golongan yang bersekutu telah mendustakan) rasul-rasulnya, seperti Ad dan Tsamud serta kaum-kaum lainnya (sesudah mereka, dan tiap-tiap umat telah merencanakan makar terhadap rasul mereka untuk menawannya) untuk membunuhnya (dan mereka membantah dengan alasan yang batil untuk melenyapkan) untuk menghapuskan (kebenaran dengan yang batil itu; karena itu Aku azab mereka) dengan siksaan. (Maka betapa pedihnya azab-Ku) terhadap mereka; hal itu sesuai dengan imbalan yang harus mereka terima.",[["كَذَّبَتْ","dinafikan"],["قَبْلَهُمْ","sebelum mereka"],["قَوْمُ","kaum"],["نُوحٍۢ","(daripada) Nuh"],["وَٱلْأَحْزَابُ","dan puak-puak"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ ۖ","selepas mereka"],["وَهَمَّتْ","dan diplot"],["كُلُّ","setiap"],["أُمَّةٍۭ","bangsa"],["بِرَسُولِهِمْ","terhadap Rasul mereka"],["لِيَأْخُذُوهُ ۖ","untuk menangkapnya"],["وَجَـٰدَلُوا۟","dan mereka berselisih"],["بِٱلْبَـٰطِلِ","oleh kepalsuan"],["لِيُدْحِضُوا۟","untuk menyangkal"],["بِهِ","dengan itu"],["ٱلْحَقَّ","kebenaran"],["فَأَخَذْتُهُمْ ۖ","Jadi aku menangkap mereka"],["فَكَيْفَ","Kemudian bagaimana"],["كَانَ","adalah"],["عِقَابِ","Penalti aku"]]],"4139":["(Dan demikianlah telah pasti berlaku ketetapan azab Rabbmu) sebagaimana yang telah diungkapkan-Nya dalam firman yang lain, yaitu, \"Sesungguhnya akan Aku penuhi neraka Jahanam itu...\" (Q.S. As-Sajdah, 13) (terhadap orang-orang kafir, karena sesungguhnya mereka adalah penghuni neraka) lafal Annahum Ashhaabun Naari merupakan Badal dari lafal Kalimatu Rabbika.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["حَقَّتْ","telah dibenarkan"],["كَلِمَتُ","(the) Firman"],["رَبِّكَ","Tuhanmu"],["عَلَى","terhadap"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَنَّهُمْ","bahawa mereka"],["أَصْحَـٰبُ","(adalah) sahabat"],["ٱلنَّارِ","(dari) api"]]],"4140":["(Malaikat-malaikat yang memikul Arasy) berkedudukan menjadi Mubtada (dan malaikat yang berada di sekelilingnya) diathafkan kepada ayat sebelumnya (bertasbih) menjadi Khabar dari Mubtada (memuji Rabb mereka) artinya, seraya memuji-Nya yaitu mengucapkan kalimat, \"Subhaanallaah Wa Bihamdihi\" (dan mereka beriman kepada-Nya) kepada Allah swt. dengan kalbu mereka, maksudnya, mereka percaya kepada keesaan-Nya (serta memintakan ampun bagi orang-orang yang beriman) seraya mengucapkan, (\"Ya Rabb kami! Rahmat dan ilmu Engkau meliputi segala sesuatu) maksudnya, rahmat-Mu meliputi segala sesuatu, dan ilmu-Mu meliputi segala sesuatu. (Maka berilah ampun kepada orang-orang yang bertobat) dari kemusyrikan (dan mengikuti jalan Engkau) yakni agama Islam (dan peliharalah mereka dari siksa neraka Jahim) yang apinya menyala-nyala.",[["ٱلَّذِينَ","Orang yang"],["يَحْمِلُونَ","beruang"],["ٱلْعَرْشَ","takhta"],["وَمَنْ","dan siapa"],["حَوْلَهُۥ","(ada) di sekelilingnya"],["يُسَبِّحُونَ","bertasbih"],["بِحَمْدِ","(the) pujian"],["رَبِّهِمْ","(dari) Tuhan mereka"],["وَيُؤْمِنُونَ","dan beriman"],["بِهِۦ","dalam Dia"],["وَيَسْتَغْفِرُونَ","dan memohon ampun"],["لِلَّذِينَ","bagi mereka yang"],["ءَامَنُوا۟","beriman"],["رَبَّنَا","Wahai Tuhan kami"],["وَسِعْتَ","Kamu merangkumi"],["كُلَّ","semua"],["شَىْءٍۢ","benda"],["رَّحْمَةًۭ","(dengan) Rahmat-Mu"],["وَعِلْمًۭا","dan pengetahuan"],["فَٱغْفِرْ","jadi maafkan"],["لِلَّذِينَ","orang yang"],["تَابُوا۟","bertaubat"],["وَٱتَّبَعُوا۟","dan ikut"],["سَبِيلَكَ","Cara Kamu"],["وَقِهِمْ","dan selamatkan mereka (daripada)"],["عَذَابَ","azab"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"4141":["(Ya Rabb kami! Masukkanlah mereka ke dalam surga Adn) sebagai tempat tinggal mereka (yang telah Engkau janjikan kepada mereka dan orang-orang yang saleh) lafal Man shalaha diathafkan kepada lafal Hum yang terdapat di dalam lafal Wa-adkhilhum atau yang terdapat pada lafal Wa'adtahum (dari bapak-bapak mereka, dan istri-istri mereka, dan keturunan mereka. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["رَبَّنَا","Wahai Tuhan kami"],["وَأَدْخِلْهُمْ","Dan akui mereka"],["جَنَّـٰتِ","(ke) Taman"],["عَدْنٍ","(dari) Eden"],["ٱلَّتِى","yang"],["وَعَدتَّهُمْ","Kamu telah berjanji kepada mereka"],["وَمَن","dan sesiapa"],["صَلَحَ","(adalah) soleh"],["مِنْ","antara"],["ءَابَآئِهِمْ","bapa mereka"],["وَأَزْوَٰجِهِمْ","dan pasangan mereka"],["وَذُرِّيَّـٰتِهِمْ ۚ","dan keturunan mereka"],["إِنَّكَ","Sesungguhnya Engkau"],["أَنتَ","kamu"],["ٱلْعَزِيزُ","(adalah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"4142":["(Dan peliharalah mereka dari kejahatan) dari balasan azabnya (Dan orang-orang yang Engkau pelihara dari balasan kejahatan pada hari itu) pada hari kiamat (maka sesungguhnya telah Engkau anugerahkan rahmat kepadanya dan itulah kemenangan yang besar.\")",[["وَقِهِمُ","Dan lindungi mereka"],["ٱلسَّيِّـَٔاتِ ۚ","(dari) kejahatan"],["وَمَن","Dan sesiapa"],["تَقِ","kamu lindungi"],["ٱلسَّيِّـَٔاتِ","(dari) kejahatan"],["يَوْمَئِذٍۢ","hari itu"],["فَقَدْ","maka sesungguhnya"],["رَحِمْتَهُۥ ۚ","Engkau telah melimpahkan rahmat kepadanya"],["وَذَٰلِكَ","Dan bahawa"],["هُوَ","[ia]"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْعَظِيمُ","yang hebat"]]],"4143":["(Sesungguhnya orang-orang yang kafir diserukan kepada mereka) oleh para malaikat, sedangkan mereka membenci diri mereka sendiri sewaktu mereka dimasukkan ke dalam neraka (\"Sesungguhnya kebencian Allah) kepada kalian (lebih besar daripada kebencian kalian kepada diri kalian sendiri karena kalian diseru) sewaktu di dunia (untuk beriman, lalu kalian kafir.\")",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["يُنَادَوْنَ","akan diseru kepada mereka"],["لَمَقْتُ","Sudah tentu Allah benci"],["ٱللَّهِ","Sudah tentu Allah benci"],["أَكْبَرُ","(adalah) lebih besar"],["مِن","daripada"],["مَّقْتِكُمْ","kebencian kamu"],["أَنفُسَكُمْ","(dari) kamu sendiri"],["إِذْ","apabila"],["تُدْعَوْنَ","kamu dipanggil"],["إِلَى","kepada"],["ٱلْإِيمَـٰنِ","iman"],["فَتَكْفُرُونَ","dan kamu telah kufur"]]],"4144":["(Mereka menjawab, \"Ya Rabb kami, Engkau telah mematikan kami dua kali) yakni dua kali mati (dan telah menghidupkan kami dua kali pula) yakni dua kali hidup. Karena sesungguhnya sebelum itu mereka berupa mani, dalam keadaan mati, kemudian mereka dijadikan hidup, lalu mereka dimatikan lagi, lalu mereka dihidupkan lagi pada hari berbangkit (lalu kami mengakui dosa-dosa kami) yaitu dosa keingkaran kami terhadap adanya hari berbangkit. (Maka adakah untuk keluar) dari neraka lalu kembali lagi ke dunia, supaya kami dapat menjalani ketaatan kepada Rabb kami (sesuatu jalan\") yakni jalan keluar, maka jawaban mereka adalah tidak ada.",[["قَالُوا۟","Mereka (akan) berkata"],["رَبَّنَآ","Wahai Tuhan kami"],["أَمَتَّنَا","Kamu memberi kami kematian"],["ٱثْنَتَيْنِ","dua kali"],["وَأَحْيَيْتَنَا","dan Engkau memberi kami kehidupan"],["ٱثْنَتَيْنِ","dua kali"],["فَٱعْتَرَفْنَا","dan kami mengaku"],["بِذُنُوبِنَا","dosa kita"],["فَهَلْ","Begitu juga (ada)"],["إِلَىٰ","kepada"],["خُرُوجٍۢ","keluar"],["مِّن","sebarang"],["سَبِيلٍۢ","cara"]]],"4145":["(Yang demikian itu) maksudnya, azab yang kalian sedang jalani itu (adalah karena) ketika di dunia (kalian kafir apabila Allah saja disembah) artinya, kalian kafir bilamana Dia diesakan. (Dan apabila Allah dipersekutukan) menjadikan sekutu bagi-Nya (kalian percaya) kalian percaya kepada kemusyrikan itu. (Maka putusan) untuk mengazab kalian (adalah pada Allah Yang Maha Tinggi) atas semua makhluk-Nya (lagi Maha Besar) Maha Agung.",[["ذَٰلِكُم","Itu"],["بِأَنَّهُۥٓ","(adalah) kerana"],["إِذَا","apabila"],["دُعِىَ","Allah telah diseru"],["ٱللَّهُ","Allah telah diseru"],["وَحْدَهُۥ","bersendirian"],["كَفَرْتُمْ ۖ","kamu tidak beriman"],["وَإِن","tetapi jika"],["يُشْرَكْ","(yang lain) telah dikaitkan"],["بِهِۦ","dengan Dia"],["تُؤْمِنُوا۟ ۚ","kamu beriman"],["فَٱلْحُكْمُ","Jadi penghakiman"],["لِلَّهِ","(ada) dengan Allah"],["ٱلْعَلِىِّ","yang Maha Tinggi"],["ٱلْكَبِيرِ","yang Maha Agung"]]],"4146":["(Dialah yang memperlihatkan kepada kalian tanda-tanda-Nya) yang menunjukkan akan keesaan-Nya (dan menurunkan untuk kalian rezeki dari langit) berupa hujan. (Dan tiadalah mendapat pelajaran) yakni mengambil nasihat (kecuali orang-orang yang kembali kepada Allah) dari kemusyrikan.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["يُرِيكُمْ","menunjukkan kepada kamu"],["ءَايَـٰتِهِۦ","Tanda-tandaNya"],["وَيُنَزِّلُ","dan menghantar ke bawah"],["لَكُم","bagi kamu"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["رِزْقًۭا ۚ","rezeki"],["وَمَا","Tetapi (tidak) tidak"],["يَتَذَكَّرُ","ambil iktibar"],["إِلَّا","kecuali"],["مَن","(satu) siapa"],["يُنِيبُ","berpusing"]]],"4147":["(Maka serulah Allah) sembahlah Dia (dengan memurnikan ibadah kepada-Nya) artinya, memurnikan agama dari kemusyrikan (meskipun orang-orang kafir tidak menyukainya) sekalipun mereka tidak menyukai keikhlasan kalian kepada-Nya.",[["فَٱدْعُوا۟","Jadi mohon"],["ٱللَّهَ","Allah"],["مُخْلِصِينَ","(bersifat) ikhlas"],["لَهُ","kepada-Nya"],["ٱلدِّينَ","(dalam) agama"],["وَلَوْ","walaupun"],["كَرِهَ","tidak suka (ia)"],["ٱلْكَـٰفِرُونَ","orang kafir"]]],"4148":["(Dialah Yang Maha Tinggi derajat-Nya) maksudnya, Allah Maha Agung sifat-sifat-Nya, atau Dialah Yang mengangkat derajat orang-orang yang beriman di surga (Yang mempunyai Arasy) Yang menciptakannya (Yang menurunkan Ar-Ruuh) yakni wahyu (dari perintah-Nya) atau firman-nya (kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya, supaya dia memperingatkan) maksudnya, orang yang menerima wahyu itu diperintahkan untuk menyampaikan wahyu-Nya kepada manusia (tentang hari pertemuan) dapat dibaca At-Talaaqi atau At-Talaaqiy dengan memakai huruf Ya. Yakni hari kiamat, karena pada hari itu penduduk langit dan penduduk bumi bertemu, dan bertemu pula antara Yang Disembah dan yang menyembah, sebagaimana dipertemukan pula antara orang yang aniaya dan orang yang dianiaya.",[["رَفِيعُ","Pemilik Pangkat Tertinggi"],["ٱلدَّرَجَـٰتِ","Pemilik Pangkat Tertinggi"],["ذُو","Pemilik (pemilik) Arasy"],["ٱلْعَرْشِ","Pemilik (pemilik) Arasy"],["يُلْقِى","Dia meletakkan"],["ٱلرُّوحَ","inspirasi"],["مِنْ","daripada"],["أَمْرِهِۦ","PerintahNya"],["عَلَىٰ","ke atas"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ","hambanya"],["لِيُنذِرَ","untuk memberi amaran"],["يَوْمَ","hari"],["ٱلتَّلَاقِ","(dari) Mesyuarat"]]],"4149":["(Yaitu hari ketika mereka keluar) dari kuburnya masing-masing (tiada suatu pun dari keadaan mereka yang tersembunyi bagi Allah berfirman, \"Kepunyaan siapakah kerajaan pada hari ini?\") Allah sendiri yang mengatakannya, kemudian Dia sendiri pula yang menjawabnya, yaitu, (\"Hanya kepunyaan Allah Yang Maha Esa lagi Maha Mengalahkan\") atas semua makhluk-Nya.",[["يَوْمَ","(The) Hari"],["هُم","mereka"],["بَـٰرِزُونَ ۖ","keluar"],["لَا","tidak"],["يَخْفَىٰ","tersembunyi"],["عَلَى","daripada"],["ٱللَّهِ","Allah"],["مِنْهُمْ","tentang mereka"],["شَىْءٌۭ ۚ","sesuatu"],["لِّمَنِ","Untuk siapa"],["ٱلْمُلْكُ","(ialah) Kekuasaan"],["ٱلْيَوْمَ ۖ","Hari ini"],["لِلَّهِ","Untuk Allah"],["ٱلْوَٰحِدِ","yang Satu"],["ٱلْقَهَّارِ","yang tak tertahan"]]],"4150":["(Pada hari ini tiap-tiap jiwa diberi balasan dengan apa yang diusahakannya. Tidak ada yang dirugikan pada hari ini. Sesungguhnya Allah amat cepat hisab-Nya) Dia menghisab semua makhluk hanya dalam waktu setengah hari dunia, demikianlah menurut keterangan hadis.",[["ٱلْيَوْمَ","Hari ini"],["تُجْزَىٰ","akan diberi ganjaran"],["كُلُّ","setiap"],["نَفْسٍۭ","jiwa"],["بِمَا","bagi apa"],["كَسَبَتْ ۚ","ia diperolehi"],["لَا","Tidak"],["ظُلْمَ","ketidakadilan"],["ٱلْيَوْمَ ۚ","hari ini"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَرِيعُ","(ialah) Swift"],["ٱلْحِسَابِ","(dalam) Akaun"]]],"4151":["(Berilah mereka peringatan dengan hari yang dekat) yakni hari kiamat. Berasal dari kata Azifar Rahiilu, artinya, Waktu berangkat telah dekat (yaitu ketika kalbu) menyesak karena dicekam rasa takut (sampai) artinya hingga sesaknya terasa sampai (di kerongkongan dengan menahan kedukaan) penuh dengan kesedihan. Lafal Kaazhimiina ini adalah Hal atau kata keterangan keadaan bagi lafal Al-Quluubu, kemudian dianggap sebagai jamak dengan memakai huruf Ya dan Nun karena diibaratkan kepada para pemiliknya. (Tiada teman-teman yang setia bagi orang-orang yang zalim) maksudnya tiada teman sejawat dan dekat (dan tidak pula mempunyai seorang pemberi syafaat yang diterima syafaatnya) yang dapat diterima syafaatnya; lafal Yuthaa'u sebagai sifat, tidak mengandung pengertian apa-apa, karena pada asalnya tiada syafaat bagi mereka, sebagaimana yang telah diungkapkan oleh firman-Nya yang lain, yaitu, \"Maka kami tidak mempunyai pemberi syafaat seorang pun.\" (Q.S. Asy-Syu'ara, 100). Tetapi kalau lafal Syafii'in, memang mengandung makna, karena ditinjau dari segi dugaan mereka yaitu, bahwasanya mereka memiliki pemberi-pemberi syafaat. Maksudnya, seandainya mereka memberi syafaat, niscaya syafaat mereka tidak akan diterima.",[["وَأَنذِرْهُمْ","Dan beri amaran kepada mereka"],["يَوْمَ","hari"],["ٱلْـَٔازِفَةِ","yang Mendekati"],["إِذِ","apabila"],["ٱلْقُلُوبُ","hati"],["لَدَى","(adalah) di"],["ٱلْحَنَاجِرِ","tekak"],["كَـٰظِمِينَ ۚ","tercekik"],["مَا","Tidak"],["لِلظَّـٰلِمِينَ","bagi orang-orang yang zalim"],["مِنْ","sebarang"],["حَمِيمٍۢ","kawan intim"],["وَلَا","dan tidak"],["شَفِيعٍۢ","pemberi syafaat"],["يُطَاعُ","(yang) ditaati"]]],"4152":["(Dia mengetahui) Allah mengetahui (mata yang khianat) ketika mencuri pandang melihat hal-hal yang diharamkan (dan apa yang disembunyikan oleh hati) yang tersimpan di dalam kalbu.",[["يَعْلَمُ","Dia tahu"],["خَآئِنَةَ","(yang) sembunyi-sembunyi"],["ٱلْأَعْيُنِ","(yang) sembunyi-sembunyi"],["وَمَا","dan apa"],["تُخْفِى","menyembunyikan"],["ٱلصُّدُورُ","buah dada"]]],"4153":["(Dan Allah menghukum dengan keadilan. Dan sesembahan-sesembahan yang mereka seru) yang mereka sembah (selain Allah) yakni berhala-berhala (tiada dapat menghukum dengan sesuatu apa pun) mana mungkin mereka menjadi sekutu-sekutu Allah? (Sesungguhnya Allah Dialah Yang Maha Mendengar) semua perkataan mereka (lagi Maha Melihat) semua perbuatan mereka.",[["وَٱللَّهُ","Dan Allah"],["يَقْضِى","hakim"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["وَٱلَّذِينَ","manakala mereka (yang)"],["يَدْعُونَ","mereka menyeru"],["مِن","selain Dia"],["دُونِهِۦ","selain Dia"],["لَا","tidak"],["يَقْضُونَ","mereka menilai"],["بِشَىْءٍ ۗ","dengan apa sahaja"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْبَصِيرُ","yang Maha Melihat"]]],"4154":["(Dan apakah mereka tidak mengadakan perjalanan di muka bumi, lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Mereka itu adalah lebih hebat daripada mereka) menurut suatu qiraat lafal Minhum dibaca Minkum, artinya lebih hebat daripada kalian (kekuatannya dan lebih banyak bekas-bekas mereka di muka bumi) seperti bangunan-bangunan dan gedung-gedungnya (maka Allah mengazab mereka) membinasakan mereka (disebabkan dosa-dosa mereka. Dan sekali-kali mereka tidak mempunyai seorang pelindung dari azab Allah) dari siksaan-Nya.",[["۞ أَوَلَمْ","Jangan"],["يَسِيرُوا۟","mereka mengembara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَيَنظُرُوا۟","dan lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلَّذِينَ","orang yang"],["كَانُوا۟","adalah"],["مِن","sebelum mereka"],["قَبْلِهِمْ ۚ","sebelum mereka"],["كَانُوا۟","Mereka"],["هُمْ","[mereka]"],["أَشَدَّ","atasan"],["مِنْهُمْ","kepada mereka"],["قُوَّةًۭ","(dalam) kekuatan"],["وَءَاثَارًۭا","dan (dalam) tera"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَأَخَذَهُمُ","tetapi Allah menimpakan mereka"],["ٱللَّهُ","tetapi Allah menimpakan mereka"],["بِذُنُوبِهِمْ","kerana dosa mereka"],["وَمَا","dan bukan"],["كَانَ","adalah"],["لَهُم","bagi mereka"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["وَاقٍۢ","pelindung"]]],"4155":["(Yang demikian itu adalah karena telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti) yakni mukjizat-mukjizat yang tampak (lalu mereka kafir; maka Allah mengazab mereka. Sesungguhnya Dia Maha Kuat lagi Maha Keras hukuman-Nya.)",[["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana [mereka]"],["كَانَت","pernah datang kepada mereka"],["تَّأْتِيهِمْ","pernah datang kepada mereka"],["رُسُلُهُم","Rasul-rasul mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَكَفَرُوا۟","tetapi mereka kafir"],["فَأَخَذَهُمُ","Maka Allah menangkap mereka"],["ٱللَّهُ ۚ","Maka Allah menangkap mereka"],["إِنَّهُۥ","Sesungguhnya Dia"],["قَوِىٌّۭ","(adalah) Maha Kuat"],["شَدِيدُ","teruk"],["ٱلْعِقَابِ","(dalam) hukuman"]]],"4156":["(Dan sesungguhnya telah Kami utus Musa dengan membawa ayat-ayat Kami dan keterangan yang nyata) bukti yang jelas dan tampak.",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَا","Kami utus"],["مُوسَىٰ","Musa"],["بِـَٔايَـٰتِنَا","dengan Tanda-tanda Kami"],["وَسُلْطَـٰنٍۢ","dan pihak berkuasa"],["مُّبِينٍ","yang nyata"]]],"4157":["(Kepada Firaun, Haman dan Qarun; maka mereka berkata,) \"Dia (adalah seorang ahli sihir yang pendusta.\")",[["إِلَىٰ","Kepada"],["فِرْعَوْنَ","Firaun"],["وَهَـٰمَـٰنَ","Haman"],["وَقَـٰرُونَ","dan Qarun"],["فَقَالُوا۟","tetapi mereka berkata"],["سَـٰحِرٌۭ","Seorang ahli silap mata"],["كَذَّابٌۭ","pembohong"]]],"4158":["(Maka tatkala Musa datang kepada mereka membawa kebenaran) yakni dengan membawa perkara yang hak (dari sisi Kami, mereka berkata, \"Bunuhlah anak-anak orang-orang yang beriman bersama dengan dia dan biarkanlah hidup) yakni biarkanlah tetap hidup (wanita-wanita mereka.\" Dan tipu daya orang-orang kafir itu tak lain hanyalah sia-sia belaka) yakni menjerumuskan mereka sendiri dalam kebinasaan.",[["فَلَمَّا","Kemudian apabila"],["جَآءَهُم","dia bawa kepada mereka"],["بِٱلْحَقِّ","kebenaran"],["مِنْ","daripada"],["عِندِنَا","Kami"],["قَالُوا۟","mereka berkata"],["ٱقْتُلُوٓا۟","Bunuh"],["أَبْنَآءَ","(anak) lelaki"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["مَعَهُۥ","dengan dia"],["وَٱسْتَحْيُوا۟","dan biarkan hidup"],["نِسَآءَهُمْ ۚ","wanita mereka"],["وَمَا","Dan tidak"],["كَيْدُ","(ialah) plot"],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"],["إِلَّا","tetapi"],["فِى","dalam"],["ضَلَـٰلٍۢ","ralat"]]],"4159":["(Dan berkata Firaun kepada pembesar-pembesarnya, \"Biarkanlah aku membunuh Musa) karena mereka mencegahnya melakukan pembunuhan terhadap Musa (dan hendaklah ia memohon kepada Rabbnya) supaya Dia mencegah niatku yang akan membunuhnya (karena sesungguhnya aku khawatir dia akan menukar agama kalian) mencegah kalian menyembahku, lalu kalian mengikutinya (atau menimbulkan kerusakan di muka bumi\") seperti melakukan pembunuhan dan lain sebagainya. Menurut suatu qiraat lafal Au dibaca Wa. Dan menurut qiraat lainnya dibaca Ay Yazhhara Fil Ardhil Fasaadu.",[["وَقَالَ","Dan berkata"],["فِرْعَوْنُ","Firaun"],["ذَرُونِىٓ","tinggalkan aku"],["أَقْتُلْ","(supaya) aku membunuh"],["مُوسَىٰ","Musa"],["وَلْيَدْعُ","dan biarkan dia memanggil"],["رَبَّهُۥٓ ۖ","Tuhannya"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["أَن","bahawa"],["يُبَدِّلَ","dia akan berubah"],["دِينَكُمْ","agama kamu"],["أَوْ","atau"],["أَن","bahawa"],["يُظْهِرَ","dia boleh menyebabkan muncul"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["ٱلْفَسَادَ","rasuah itu"]]],"4160":["(Dan Musa berkata,) kepada kaumnya sedangkan dia telah mendengar ancaman Firaun tadi (\"Sesungguhnya aku berlindung kepada Rabbku dan Rabb kalian dari setiap orang yang menyombongkan diri yang tidak beriman kepada hari berhisab.\")",[["وَقَالَ","Dan berkata"],["مُوسَىٰٓ","Musa"],["إِنِّى","Sesungguhnya aku"],["عُذْتُ","[Aku] mencari perlindungan"],["بِرَبِّى","dalam Tuhanku"],["وَرَبِّكُم","dan Tuhanmu"],["مِّن","daripada"],["كُلِّ","setiap"],["مُتَكَبِّرٍۢ","seorang yang sombong"],["لَّا","tidak"],["يُؤْمِنُ","yang beriman"],["بِيَوْمِ","(dalam) Hari"],["ٱلْحِسَابِ","(daripada) Akaun"]]],"4161":["(Dan berkatalah seorang laki-laki yang beriman di antara keluarga Firaun) menurut suatu pendapat disebutkan, bahwa ia adalah anak paman Firaun atau saudara sepupunya (yang menyembunyikan imannya, \"Apakah kalian akan membunuh seorang laki-laki karena) sebab (dia menyatakan, 'Rabbku ialah Allah' padahal dia telah datang kepada kalian dengan membawa keterangan-keterangan) yakni mukjizat-mukjizat yang jelas (dari Rabb kalian. Dan jika ia seorang pendusta maka dialah yang menanggung dosa-dustanya itu) yakni dia sendirilah yang menanggung akibat dari kedustaannya (dan jika ia seorang yang benar niscaya sebagian bencana yang diancamkannya kepada kalian akan menimpa kalian\") yakni sebagian azab yang diancamkannya kepada kalian akan segera menimpa diri kalian. (Sesungguhnya Allah tidak menunjuki orang-orang yang melampaui batas) yakni orang yang musyrik (lagi pendusta) yang banyak dustanya.",[["وَقَالَ","Dan berkata"],["رَجُلٌۭ","seorang lelaki"],["مُّؤْمِنٌۭ","beriman"],["مِّنْ","daripada"],["ءَالِ","(keluarga)."],["فِرْعَوْنَ","(daripada) Firaun"],["يَكْتُمُ","yang menyembunyikan(ed)"],["إِيمَـٰنَهُۥٓ","imannya"],["أَتَقْتُلُونَ","Adakah kamu akan membunuh"],["رَجُلًا","seorang lelaki"],["أَن","kerana"],["يَقُولَ","katanya"],["رَبِّىَ","Tuhanku"],["ٱللَّهُ","(ialah) Allah"],["وَقَدْ","dan sesungguhnya"],["جَآءَكُم","dia telah membawa kamu"],["بِٱلْبَيِّنَـٰتِ","bukti yang jelas"],["مِن","daripada"],["رَّبِّكُمْ ۖ","Tuhanmu"],["وَإِن","Dan jika"],["يَكُ","dia adalah"],["كَـٰذِبًۭا","pembohong"],["فَعَلَيْهِ","kemudian ke atasnya"],["كَذِبُهُۥ ۖ","(adalah) pembohongannya"],["وَإِن","dan jika"],["يَكُ","dia adalah"],["صَادِقًۭا","jujur"],["يُصِبْكُم","(di sana) akan menyerang kamu"],["بَعْضُ","beberapa (daripada)"],["ٱلَّذِى","(itu) yang"],["يَعِدُكُمْ ۖ","dia ugut kamu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["مَنْ","(satu) siapa"],["هُوَ","[dia]"],["مُسْرِفٌۭ","(adalah) penceroboh"],["كَذَّابٌۭ","pembohong"]]],"4162":["(Hai kaumku! Untuk kalianlah kerajaan pada hari ini dengan berkuasa) artinya, dengan mengalami kemenangan; lafal Zhaahiriina berkedudukan menjadi Hal atau kata keterangan keadaan (di muka bumi) di negeri Mesir. (Siapakah yang akan menolong kita dari azab Allah) dari azab-Nya bila kalian membunuh kekasih-kekasih-Nya (jika azab itu menimpa kita) tiada seorang pun yang dapat menolong kita (Firaun berkata, \"Aku tidak mengemukakan kepada kalian, melainkan apa yang aku pandang baik;) maksudnya, aku tidak memberikan isyarat kepada kalian melainkan apa yang telah aku putuskan itu, yaitu membunuh Musa (dan aku tiada menunjukkan kepada kalian, selain jalan yang benar\") jalan yang mengandung kebenaran.",[["يَـٰقَوْمِ","Wahai kaumku"],["لَكُمُ","Untuk kamu"],["ٱلْمُلْكُ","(ialah) kerajaan"],["ٱلْيَوْمَ","hari ini"],["ظَـٰهِرِينَ","dominan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَمَن","tetapi siapa"],["يَنصُرُنَا","akan membantu kita"],["مِنۢ","daripada"],["بَأْسِ","azab"],["ٱللَّهِ","(milik) Allah"],["إِن","jika"],["جَآءَنَا ۚ","ia datang kepada kami"],["قَالَ","Berkata"],["فِرْعَوْنُ","Firaun"],["مَآ","Tidak"],["أُرِيكُمْ","aku tunjukkan"],["إِلَّا","kecuali"],["مَآ","apa"],["أَرَىٰ","aku nampak"],["وَمَآ","dan bukan"],["أَهْدِيكُمْ","aku bimbing kamu"],["إِلَّا","kecuali"],["سَبِيلَ","(ke) jalan"],["ٱلرَّشَادِ","yang betul"]]],"4163":["(Dan orang yang beriman itu berkata, \"Hai kaumku! Sesungguhnya aku khawatir kalian akan ditimpa -bencana- seperti peristiwa kehancuran golongan yang bersekutu) yakni azab yang telah menimpa umat-umat terdahulu, golongan demi golongan.",[["وَقَالَ","Dan berkata"],["ٱلَّذِىٓ","(dia) siapa"],["ءَامَنَ","beriman"],["يَـٰقَوْمِ","Wahai kaumku"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["عَلَيْكُم","bagi kamu"],["مِّثْلَ","suka"],["يَوْمِ","(hari itu)."],["ٱلْأَحْزَابِ","(daripada) syarikat"]]],"4164":["(-Yakni- seperti keadaan kaum Nuh, Ad, Tsamud dan orang-orang yang datang sesudah mereka) lafal Mitsli dalam ayat ini merupakan Badal atau pengganti keterangan dari lafal Mitsli yang sebelumnya, yang ada pada ayat di atas. Yakni, seperti pembalasan yang biasa menimpa orang-orang kafir sebelum kalian; mereka ditimpa azab di dunia. (Dan Allah tidak menghendaki berbuat kelaliman terhadap hamba-hamba-Nya.)",[["مِثْلَ","Suka"],["دَأْبِ","(the) kesusahan"],["قَوْمِ","(daripada) orang ramai"],["نُوحٍۢ","(daripada) Nuh"],["وَعَادٍۢ","dan Aad"],["وَثَمُودَ","dan kaum Thamud"],["وَٱلَّذِينَ","dan mereka"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ ۚ","selepas mereka"],["وَمَا","Dan Allah tidak"],["ٱللَّهُ","Dan Allah tidak"],["يُرِيدُ","mahu"],["ظُلْمًۭا","ketidakadilan"],["لِّلْعِبَادِ","untuk hamba-hamba-Nya"]]],"4165":["(Hai kaumku, sesungguhnya aku khawatir terhadap kalian akan siksa hari panggil-memanggil) dapat dibaca At-Tanaadi atau At-Tanaadiy dengan memakai huruf Ya pada akhirnya. Artinya ialah hari kiamat, yang pada hari itu banyak sekali panggil-memanggil antara ahli surga dan ahli neraka; setiap panggilan sesuai dengan apa yang dialami oleh pemanggilnya. Maka panggilan yang mengandung kebahagiaan adalah bagi ahli surga dan panggilan yang mengandung kecelakaan adalah bagi ahli neraka; selain itu masih banyak pula jenis panggilan atau seruan lainnya.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["عَلَيْكُمْ","bagi kamu"],["يَوْمَ","(the) Hari"],["ٱلتَّنَادِ","(daripada) Memanggil"]]],"4166":["(Yaitu hari ketika kalian lari berpaling ke belakang) dari tempat hisab untuk dibawa ke neraka (tidak ada bagi kalian dari Allah) yakni dari azab-Nya (seorang pun yang dapat menyelamatkan kalian) yakni yang dapat mencegah azab dari diri kalian (dan siapa yang disesatkan Allah, niscaya tidak ada baginya seorang pun yang akan memberi petunjuk.\")",[["يَوْمَ","Sehari"],["تُوَلُّونَ","kamu akan berpatah balik"],["مُدْبِرِينَ","melarikan diri"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["مِنْ","sebarang"],["عَاصِمٍۢ ۗ","pelindung"],["وَمَن","Dan sesiapa"],["يُضْلِلِ","Allah biarkan sesat"],["ٱللَّهُ","Allah biarkan sesat"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِنْ","sebarang"],["هَادٍۢ","panduan"]]],"4167":["(Dan sesungguhnya telah datang Yusuf kepada kalian sebelumnya) yakni sebelum Nabi Musa; menurut suatu pendapat ia adalah Yusuf bin Yakub yang usianya dipanjangkan sampai zaman Nabi Musa; atau menurut pendapat yang lain dia adalah Yusuf bin Ibrahim bin Yusuf bin Nabi Yakub (dengan membawa keterangan-keterangan) mukjizat-mukjizat yang tampak jelas (tetapi kalian senantiasa dalam keraguan tentang apa yang dibawanya kepada kalian, sehingga ketika dia meninggal, kalian berkata,) tanpa memakai bukti yang benar lagi (\"Allah tidak akan mengirim seorang rasul pun sesudahnya.\") selagi kalian masih tetap dalam keadaan kafir atau ingkar kepada Nabi Yusuf dan rasul-rasul lainnya. (Demikianlah) maksudnya sebagaimana kalian disesatkan (Allah menyesatkan orang yang melampaui batas) yakni orang yang musyrik (lagi ragu-ragu) artinya, tidak percaya kepada mukjizat-mukjizat yang telah disaksikannya sendiri.",[["وَلَقَدْ","Dan sesungguhnya"],["جَآءَكُمْ","datang kepada kamu"],["يُوسُفُ","Yusuf"],["مِن","sebelum"],["قَبْلُ","sebelum"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَمَا","tetapi tidak"],["زِلْتُمْ","kamu berhenti"],["فِى","dalam"],["شَكٍّۢ","keraguan"],["مِّمَّا","tentang apa"],["جَآءَكُم","dia bawakan kepada kamu"],["بِهِۦ ۖ","[dengannya]"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["هَلَكَ","dia meninggal dunia"],["قُلْتُمْ","kamu kata"],["لَن","tidak pernah"],["يَبْعَثَ","akan Allah bangkitkan"],["ٱللَّهُ","akan Allah bangkitkan"],["مِنۢ","selepas dia"],["بَعْدِهِۦ","selepas dia"],["رَسُولًۭا ۚ","seorang Rasul"],["كَذَٰلِكَ","Demikianlah"],["يُضِلُّ","Allah biarkan sesat"],["ٱللَّهُ","Allah biarkan sesat"],["مَنْ","yang"],["هُوَ","[dia]"],["مُسْرِفٌۭ","(adalah) penceroboh"],["مُّرْتَابٌ","seorang yang ragu-ragu"]]],"4168":["(Orang-orang yang memperdebatkan ayat-ayat Allah) yaitu mukjizat-mukjizatnya; kalimat ayat ini menjadi Mubtada (tanpa alasan) tanpa argumentasi (yang datang kepada mereka. Amat besar) dosa perdebatan mereka itu, lafal Kabura ini menjadi Khabar dari Mubtada (kemurkaan -bagi mereka- di sisi Allah dan di sisi orang-orang yang beriman. Demikianlah) sebagaimana disesatkan-Nya mereka (Allah mengunci mati) artinya, menyesatkan (hati setiap orang yang sombong lagi sewenang-wenang) dapat dibaca Qalbin Mutakabbirin atau Qalbi Mutakabbirin. Manakala kalbu seseorang merasa sombong, maka takaburlah pemiliknya, dan demikian pula sebaliknya. Lafal Kullun menurut dua qiraat di atas menunjukkan makna tiap-tiap orang yang memiliki kalbu yang sesat, jadi bukan ditujukan kepada semua orang.",[["ٱلَّذِينَ","Orang yang"],["يُجَـٰدِلُونَ","pertikaian"],["فِىٓ","tentang"],["ءَايَـٰتِ","(the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["بِغَيْرِ","tanpa"],["سُلْطَـٰنٍ","mana-mana pihak berkuasa"],["أَتَىٰهُمْ ۖ","(telah) datang kepada mereka"],["كَبُرَ","(ia) adalah sangat"],["مَقْتًا","penuh kebencian"],["عِندَ","dekat Allah"],["ٱللَّهِ","dekat Allah"],["وَعِندَ","dan dekat"],["ٱلَّذِينَ","mereka"],["ءَامَنُوا۟ ۚ","yang beriman"],["كَذَٰلِكَ","Demikianlah"],["يَطْبَعُ","Allah meletakkan meterai"],["ٱللَّهُ","Allah meletakkan meterai"],["عَلَىٰ","atas"],["كُلِّ","setiap"],["قَلْبِ","hati"],["مُتَكَبِّرٍۢ","(dari) seorang yang sombong"],["جَبَّارٍۢ","zalim"]]],"4169":["(Dan berkatalah Firaun, \"Hai Haman! Buatkanlah bagiku sebuah bangunan yang tinggi) bangunan pencakar langit (supaya aku sampai ke pintu-pintu.)",[["وَقَالَ","Dan berkata"],["فِرْعَوْنُ","Firaun"],["يَـٰهَـٰمَـٰنُ","Wahai Haman"],["ٱبْنِ","Membina"],["لِى","untuk aku"],["صَرْحًۭا","sebuah menara"],["لَّعَلِّىٓ","yang aku boleh"],["أَبْلُغُ","capai"],["ٱلْأَسْبَـٰبَ","cara-cara"]]],"4170":["(Yaitu pintu-pintu langit) maksudnya, jalan-jalan yang menuju ke arahnya (supaya aku dapat melihat) kalau dibaca Rafa', yaitu Fa-aththali'u berarti di'athafkan pada lafal Ablughu, apabila dibaca Fa-aththali'a berarti menjadi Jawab daripada Fi'il Amar, yaitu lafal Ibni (Tuhan Musa dan sesungguhnya aku memandangnya) menganggap Musa (seorang pendusta\") karena ia mengatakan, bahwa ia mempunyai Tuhan selain aku. Firaun mengatakan demikian untuk mengelabui pengikut-pengikutnya. (Demikianlah dijadikan Firaun memandang baik perbuatan yang buruk itu, dan dia dihalangi dari jalan) petunjuk; dapat dibaca Shadda sehingga artinya menjadi, Dan Firaun menghalangi jalan petunjuk dapat pula dibaca Shudda yang artinya telah tertera di atas (dan tipu daya Firaun itu tidak lain hanyalah membawa kerugian) mengakibatkan kerugian.",[["أَسْبَـٰبَ","(The) cara"],["ٱلسَّمَـٰوَٰتِ","(ke) langit"],["فَأَطَّلِعَ","jadi aku boleh melihat"],["إِلَىٰٓ","di"],["إِلَـٰهِ","(yang) Tuhan"],["مُوسَىٰ","(dari) Musa"],["وَإِنِّى","dan sesungguhnya, aku"],["لَأَظُنُّهُۥ","[Aku] pasti fikir dia"],["كَـٰذِبًۭا ۚ","(menjadi) pendusta"],["وَكَذَٰلِكَ","Dan dengan demikian"],["زُيِّنَ","telah dibuat kelihatan adil"],["لِفِرْعَوْنَ","kepada Firaun"],["سُوٓءُ","(yang) jahat"],["عَمَلِهِۦ","(dari) perbuatannya"],["وَصُدَّ","dan dia dielakkan"],["عَنِ","daripada"],["ٱلسَّبِيلِ ۚ","caranya"],["وَمَا","Dan tidak"],["كَيْدُ","(ialah) plot"],["فِرْعَوْنَ","(daripada) Firaun"],["إِلَّا","kecuali"],["فِى","dalam"],["تَبَابٍۢ","kehancuran"]]],"4171":["(Orang yang beriman itu berkata, \"Hai kaumku! Ikutilah aku) dapat dibaca Ittabi'uuni atau Ittabi'uuniy tanpa atau dengan Ya Mutakallim (aku akan menunjukkan kepada kalian jalan yang benar) penafsirannya sebagaimana yang telah lalu.",[["وَقَالَ","Dan berkata"],["ٱلَّذِىٓ","orang yang"],["ءَامَنَ","beriman"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱتَّبِعُونِ","ikut aku"],["أَهْدِكُمْ","Aku akan membimbing kamu"],["سَبِيلَ","(ke) jalan"],["ٱلرَّشَادِ","yang betul"]]],"4172":["(Hai kaumku, sesungguhnya kehidupan dunia ini hanyalah kesenangan -sementara-) kesenangan yang bersifat sementara lenyap (dan sesungguhnya akhirat itulah negeri yang kekal.)",[["يَـٰقَوْمِ","Wahai kaumku"],["إِنَّمَا","Hanya"],["هَـٰذِهِ","ini"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا","dunia"],["مَتَـٰعٌۭ","(adalah) kenikmatan"],["وَإِنَّ","dan sesungguhnya"],["ٱلْـَٔاخِرَةَ","akhirat"],["هِىَ","ia"],["دَارُ","(adalah) rumah"],["ٱلْقَرَارِ","(dari) penyelesaian"]]],"4173":["(Barang siapa yang mengerjakan perbuatan jahat, maka dia tidak akan dibalas melainkan sebanding dengan kejahatan itu. Dan barang siapa mengerjakan amal yang saleh, baik laki-laki maupun perempuan sedang ia dalam keadaan beriman, maka mereka akan masuk surga) dapat dibaca Yudkhaluuna atau Yadkhuluuna (mereka diberi rezeki di dalamnya tanpa hisab) diberi rezeki yang banyak tanpa perhitungan.",[["مَنْ","Siapa pun"],["عَمِلَ","tidak"],["سَيِّئَةًۭ","satu kejahatan"],["فَلَا","maka tidak"],["يُجْزَىٰٓ","dia akan mendapat balasan"],["إِلَّا","tetapi"],["مِثْلَهَا ۖ","(yang) seperti itu"],["وَمَنْ","dan sesiapa"],["عَمِلَ","tidak"],["صَـٰلِحًۭا","benar (perbuatan)"],["مِّن","daripada"],["ذَكَرٍ","lelaki"],["أَوْ","atau"],["أُنثَىٰ","perempuan"],["وَهُوَ","sedangkan dia"],["مُؤْمِنٌۭ","(adalah) seorang yang beriman"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["يَدْخُلُونَ","akan masuk"],["ٱلْجَنَّةَ","Syurga"],["يُرْزَقُونَ","mereka akan diberi rezeki"],["فِيهَا","di dalamnya"],["بِغَيْرِ","tanpa"],["حِسَابٍۢ","akaun"]]],"4174":["(Hai kaumku bagaimanakah kalian, aku menyeru kalian kepada keselamatan, tetapi kalian menyeru aku ke neraka.)",[["۞ وَيَـٰقَوْمِ","Dan wahai kaumku"],["مَا","Apakah (ada)"],["لِىٓ","untuk aku"],["أَدْعُوكُمْ","(itu) aku panggil kamu"],["إِلَى","kepada"],["ٱلنَّجَوٰةِ","keselamatan"],["وَتَدْعُونَنِىٓ","semasa kamu memanggil aku"],["إِلَى","kepada"],["ٱلنَّارِ","neraka"]]],"4175":["(-Kenapa- kalian menyeruku supaya kafir kepada Allah dan mempersekutukan-Nya dengan apa yang tidak kuketahui padahal aku menyeru kalian -beriman- kepada Yang Maha Perkasa) Yang Maha Menang atas semua perkara-Nya (lagi Maha Pengampun?) kepada orang yang bertobat kepada-Nya.",[["تَدْعُونَنِى","Kamu panggil aku"],["لِأَكْفُرَ","yang aku tidak beriman"],["بِٱللَّهِ","kepada Allah"],["وَأُشْرِكَ","dan (untuk) bersekutu"],["بِهِۦ","dengan Dia"],["مَا","apa"],["لَيْسَ","tidak"],["لِى","untuk aku"],["بِهِۦ","daripadanya"],["عِلْمٌۭ","sebarang pengetahuan"],["وَأَنَا۠","dan aku"],["أَدْعُوكُمْ","panggil kamu"],["إِلَى","kepada"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْغَفَّـٰرِ","Yang Maha Pengampun"]]],"4176":["(Sudah pasti) yakni pastilah (bahwa apa yang kalian seru supaya aku -beriman- kepadanya) artinya, supaya aku menyembahnya (tidak dapat memperkenankan seruan apa pun) maksudnya, tidak dapat memperkenankan suatu doa pun (baik di dunia maupun di akhirat. Dan sesungguhnya kita kembali) atau kembali kita (kepada Allah dan sesungguhnya orang-orang yang melampaui batas) yakni orang-orang kafir (mereka itulah penghuni neraka.)",[["لَا","Tidak"],["جَرَمَ","keraguan"],["أَنَّمَا","itu apa"],["تَدْعُونَنِىٓ","kamu panggil aku"],["إِلَيْهِ","kepadanya"],["لَيْسَ","tidak"],["لَهُۥ","baginya"],["دَعْوَةٌۭ","suatu tuntutan"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["وَأَنَّ","dan bahawa"],["مَرَدَّنَآ","kepulangan kami"],["إِلَى","(adalah) kepada"],["ٱللَّهِ","Allah"],["وَأَنَّ","dan bahawa"],["ٱلْمُسْرِفِينَ","orang yang melampaui batas"],["هُمْ","mereka"],["أَصْحَـٰبُ","(akan menjadi) sahabat"],["ٱلنَّارِ","(dari) api"]]],"4177":["(Kelak kalian akan ingat) bila kalian menyaksikan azab dengan mata kalian sendiri (kepada apa yang kukatakan kepada kalian. Dan aku menyerahkan urusanku kepada Allah. Sesungguhnya Allah Maha melihat akan hamba-hamba-Nya\") Ia mengatakan demikian ketika mereka mengancamnya jika ia menentang agama mereka.",[["فَسَتَذْكُرُونَ","Dan kamu akan ingat"],["مَآ","apa"],["أَقُولُ","aku cakap"],["لَكُمْ ۚ","kepada kamu"],["وَأُفَوِّضُ","dan aku amanahkan"],["أَمْرِىٓ","urusan aku"],["إِلَى","kepada"],["ٱللَّهِ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بَصِيرٌۢ","(ialah) Maha Melihat"],["بِٱلْعِبَادِ","daripada hamba-hamba-Nya"]]],"4178":["(Maka Allah memeliharanya dari kejahatan tipu daya mereka) terhadap dirinya, yaitu mereka merencanakan akan membunuhnya (dan turunlah) menimpa (kepada keluarga Firaun) maksudnya, kepada kaumnya yang mengikutinya (azab yang buruk) yaitu ditenggelamkan.",[["فَوَقَىٰهُ","Maka Allah melindunginya"],["ٱللَّهُ","Maka Allah melindunginya"],["سَيِّـَٔاتِ","(dari) kejahatan"],["مَا","bahawa"],["مَكَرُوا۟ ۖ","mereka merancang"],["وَحَاقَ","dan diselubungi"],["بِـَٔالِ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["سُوٓءُ","(yang) paling teruk"],["ٱلْعَذَابِ","hukuman"]]],"4179":["Kemudian (neraka ditampakkan kepada mereka) maksudnya, mereka dibakar oleh api neraka (pada pagi dan petang) di setiap pagi dan petang (dan pada hari terjadinya kiamat) dikatakan kepada mereka, (\"Masuklah kalian) hai (Firaun dan kaumnya) menurut suatu qiraat dibaca Adkhiluu yang artinya, Masukkanlah Firaun dan kaumnya. Ini merupakan perintah Allah kepada malaikat-malaikat-Nya (ke dalam azab yang sangat keras\") yakni azab neraka",[["ٱلنَّارُ","Api"],["يُعْرَضُونَ","mereka terdedah"],["عَلَيْهَا","kepadanya"],["غُدُوًّۭا","pagi"],["وَعَشِيًّۭا ۖ","dan petang"],["وَيَوْمَ","Dan (hari) itu"],["تَقُومُ","(akan) ditegakkan"],["ٱلسَّاعَةُ","Jam itu"],["أَدْخِلُوٓا۟","Sebab masuk"],["ءَالَ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["أَشَدَّ","(dalam) paling teruk"],["ٱلْعَذَابِ","hukuman"]]],"4180":["(Dan) ingatlah (ketika mereka berbantah) yaitu ketika orang-orang kafir saling berbantah-bantahan (dalam neraka, maka orang-orang yang lemah berkata kepada orang-orang yang menyombongkan diri, \"Sesungguhnya kami adalah pengikut-pengikut kalian) lafal Taba'an adalah bentuk jamak dari lafal Taabi'un (maka dapatkah kalian menghindarkan) artinya menolak (dari kami sebagian) yakni suatu bagian dari (azab api neraka?\")",[["وَإِذْ","Dan apabila"],["يَتَحَآجُّونَ","mereka akan mempertikaikan"],["فِى","dalam"],["ٱلنَّارِ","neraka"],["فَيَقُولُ","kemudian akan berkata"],["ٱلضُّعَفَـٰٓؤُا۟","yang lemah"],["لِلَّذِينَ","kepada mereka yang"],["ٱسْتَكْبَرُوٓا۟","adalah sombong"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","[kami] dulu"],["لَكُمْ","bagi kamu"],["تَبَعًۭا","pengikut"],["فَهَلْ","jadi boleh"],["أَنتُم","kamu"],["مُّغْنُونَ","mengelak"],["عَنَّا","daripada kami"],["نَصِيبًۭا","sebahagian"],["مِّنَ","daripada"],["ٱلنَّارِ","neraka"]]],"4181":["(Orang-orang yang menyombongkan diri menjawab, \"Sesungguhnya kita semua sama-sama dalam neraka karena sesungguhnya Allah telah menetapkan keputusan antara hamba-hamba-Nya\") oleh karena itu maka Dia memasukkan orang-orang yang beriman ke dalam surga, dan orang-orang kafir ke dalam neraka.",[["قَالَ","Akan berkata"],["ٱلَّذِينَ","orang yang"],["ٱسْتَكْبَرُوٓا۟","(berada) sombong"],["إِنَّا","Sesungguhnya kami"],["كُلٌّۭ","semua"],["فِيهَآ","(ada) di dalamnya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["قَدْ","sudah tentu"],["حَكَمَ","telah menilai"],["بَيْنَ","antara"],["ٱلْعِبَادِ","hamba-hambanya"]]],"4182":["(Dan orang-orang yang berada di dalam neraka berkata kepada penjaga-penjaga neraka Jahanam, \"Mohonkanlah kepada Rabb kalian supaya Dia meringankan daripada kami barang sehari) atau selama sehari (dari azab ini.\")",[["وَقَالَ","Dan akan berkata"],["ٱلَّذِينَ","mereka"],["فِى","dalam"],["ٱلنَّارِ","neraka"],["لِخَزَنَةِ","kepada (para) penjaga"],["جَهَنَّمَ","(dari) Neraka"],["ٱدْعُوا۟","Panggil"],["رَبَّكُمْ","Tuhanmu"],["يُخَفِّفْ","(untuk) meringankan"],["عَنَّا","bagi kami"],["يَوْمًۭا","sehari"],["مِّنَ","daripada"],["ٱلْعَذَابِ","azab"]]],"4183":["(Para penjaga neraka Jahanam berkata) dengan nada sinis, (\"Dan apakah belum datang kepada kalian rasul-rasul kalian dengan membawa keterangan-keterangan?\") yakni mukjizat-mukjizat yang tampak. (Mereka menjawab, \"Benar, sudah datang\") tetapi mereka kafir kepada rasul-rasul mereka itu. (Penjaga-penjaga Jahanam berkata, \"Berdoalah kalian\") karena sesungguhnya kami tidak akan memberikan syafaat/pertolongan kepada orang-orang kafir. Lalu Allah berfirman, (Tiadalah doa orang-orang kafir itu melainkan sia-sia belaka) yakni tiada gunanya, karena pasti tidak akan diperkenankan.",[["قَالُوٓا۟","Mereka (akan) berkata"],["أَوَلَمْ","Adakah di sana tidak"],["تَكُ","Adakah di sana tidak"],["تَأْتِيكُمْ","datang kepada kamu"],["رُسُلُكُم","Rasul-rasul kamu"],["بِٱلْبَيِّنَـٰتِ ۖ","dengan bukti yang jelas"],["قَالُوا۟","Mereka (akan) berkata"],["بَلَىٰ ۚ","ya"],["قَالُوا۟","Mereka (akan) berkata"],["فَٱدْعُوا۟ ۗ","Kemudian telefon"],["وَمَا","tetapi tidak"],["دُعَـٰٓؤُا۟","(ialah) panggilan"],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"],["إِلَّا","kecuali"],["فِى","dalam"],["ضَلَـٰلٍ","ralat"]]],"4184":["(Sesungguhnya Kami menolong rasul-rasul Kami dan orang-orang yang beriman dalam kehidupan dunia dan pada hari berdirinya saksi-saksi) yaitu hari kiamat. Lafal Al-Asyhaad adalah bentuk jamak dari lafal Syaahidun; para saksi tersebut adalah malaikat-malaikat yang memberikan kesaksian bagi para rasul, bahwasanya rasul-rasul itu telah menyampaikan risalah-Nya dan mereka mendustakan orang-orang kafir.",[["إِنَّا","Sesungguhnya Kami"],["لَنَنصُرُ","Kami pasti akan membantu"],["رُسُلَنَا","Rasul-rasul Kami"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَيَوْمَ","dan (pada) Hari"],["يَقُومُ","(apabila) akan berdiri"],["ٱلْأَشْهَـٰدُ","para saksi"]]],"4185":["(Yaitu hari yang tidak berguna) dapat dibaca Yanfa'u atau Tanfa'u (bagi orang-orang zalim permintaan maafnya) yakni permintaan maaf mereka seandainya mereka meminta maaf (dan bagi merekalah laknat) yaitu dijauhkan dari rahmat Allah (dan bagi mereka tempat tinggal yang buruk) di akhirat, yaitu mendapat azab yang sangat pedih.",[["يَوْمَ","(The) Hari"],["لَا","tidak"],["يَنفَعُ","akan mendapat manfaat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["مَعْذِرَتُهُمْ ۖ","alasan mereka"],["وَلَهُمُ","dan untuk mereka"],["ٱللَّعْنَةُ","(ialah) laknat"],["وَلَهُمْ","dan untuk mereka"],["سُوٓءُ","(adalah) yang paling teruk"],["ٱلدَّارِ","rumah"]]],"4186":["(Dan sesungguhnya telah Kami berikan petunjuk kepada Musa) berupa kitab Taurat dan mukjizat-mukjizat (dan Kami wariskan kepada Bani Israel) sesudah Musa tiada (kitab) yakni Taurat.",[["وَلَقَدْ","Dan sungguh"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْهُدَىٰ","bimbingan"],["وَأَوْرَثْنَا","dan Kami wariskan"],["بَنِىٓ","(the) Bani Israel"],["إِسْرَٰٓءِيلَ","(the) Bani Israel"],["ٱلْكِتَـٰبَ","Kitab"]]],"4187":["(Untuk menjadi petunjuk) sebagai petunjuk (dan peringatan bagi orang-orang yang berpikir) sebagai peringatan buat orang-orang yang berakal.",[["هُدًۭى","Panduan"],["وَذِكْرَىٰ","dan peringatan"],["لِأُو۟لِى","untuk mereka"],["ٱلْأَلْبَـٰبِ","(dari) pemahaman"]]],"4188":["(Maka bersabarlah kamu) hai Muhammad (karena sesungguhnya janji Allah itu) untuk menolong kekasih-kekasih-Nya (benar) dan kamu beserta orang-orang yang mengikutimu adalah termasuk kekasih-kekasih-Nya (dan mohonlah ampun untuk dosamu) supaya hal ini dijadikan teladan bagi umatmu (dan bertasbihlah) yakni, salatlah seraya (memuji Rabbmu pada waktu petang) yaitu sesudah matahari tergelincir (dan pagi) yang dimaksud adalah salat lima waktu.",[["فَٱصْبِرْ","Jadi bersabarlah"],["إِنَّ","sesungguhnya"],["وَعْدَ","(janji) Allah"],["ٱللَّهِ","(janji) Allah"],["حَقٌّۭ","(adalah) benar"],["وَٱسْتَغْفِرْ","Dan minta ampun"],["لِذَنۢبِكَ","kerana dosamu"],["وَسَبِّحْ","dan bertasbih"],["بِحَمْدِ","(yang) pujian"],["رَبِّكَ","Tuhanmu"],["بِٱلْعَشِىِّ","pada waktu petang"],["وَٱلْإِبْكَـٰرِ","dan pagi"]]],"4189":["(Sesungguhnya orang-orang yang memperdebatkan tentang ayat-ayat Allah) yakni Alquran (tanpa alasan) tanpa argumentasi (yang sampai kepada mereka, tidak ada) (dalam dada mereka melainkan hanyalah keinginan akan kebesaran) yakni tinggi diri dan tamak ingin mengatasi kamu (yang mereka sekali-kali tiada akan mencapainya maka mintalah perlindungan) dari kejahatan mereka (kepada Allah. Sesungguhnya Dia Maha Mendengar) akan semua perkataan mereka (lagi Maha Melihat) keadaan mereka; ayat ini diturunkan berkenaan dengan orang-orang yang ingkar kepada hari berbangkit.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُجَـٰدِلُونَ","pertikaian"],["فِىٓ","tentang"],["ءَايَـٰتِ","(the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["بِغَيْرِ","tanpa"],["سُلْطَـٰنٍ","mana-mana pihak berkuasa"],["أَتَىٰهُمْ ۙ","(yang) datang kepada mereka"],["إِن","tidak"],["فِى","(berada) dalam"],["صُدُورِهِمْ","buah dada mereka"],["إِلَّا","tetapi"],["كِبْرٌۭ","kehebatan"],["مَّا","tidak"],["هُم","mereka"],["بِبَـٰلِغِيهِ ۚ","(boleh) mencapainya"],["فَٱسْتَعِذْ","Maka berlindunglah"],["بِٱللَّهِ ۖ","kepada Allah"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْبَصِيرُ","yang Maha Melihat"]]],"4190":["(Sesungguhnya penciptaan langit dan bumi) yakni permulaannya (lebih besar daripada penciptaan manusia) untuk yang kedua kalinya, yaitu mengulanginya (tetapi kebanyakan manusia) yakni orang-orang kafir Mekah (tidak mengetahui) hal tersebut, perihal mereka sama dengan orang buta, sedangkan orang yang mengetahui hal tersebut perumpamaannya sama dengan orang yang melihat.",[["لَخَلْقُ","Sesungguhnya penciptaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["أَكْبَرُ","(adalah) lebih besar"],["مِنْ","daripada"],["خَلْقِ","(the) penciptaan"],["ٱلنَّاسِ","(dari) manusia"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"4191":["(Dan tidaklah sama orang yang buta dengan orang yang melihat, dan) tidak sama pula (orang-orang yang beriman serta mengerjakan amal saleh) yaitu orang yang selalu berbuat kebaikan (dengan orang-orang yang durhaka) di dalam lafal ayat ini terdapat tambahan huruf Laa (Sedikit sekali kalian mengambil pelajaran) mengambil nasihat; dapat dibaca Yatadzakkaruuna atau Tatadzakkaruuna, yakni kesadaran mereka terhadap hal ini sangat sedikit.",[["وَمَا","Dan tidak"],["يَسْتَوِى","(adalah) sama"],["ٱلْأَعْمَىٰ","yang buta"],["وَٱلْبَصِيرُ","dan yang melihat"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["وَلَا","dan bukan"],["ٱلْمُسِىٓءُ ۚ","si penjahat"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تَتَذَكَّرُونَ","kamu ambil iktibar"]]],"4192":["(Sesungguhnya hari kiamat pasti akan datang, tidak ada keraguan) artinya, tidak diragukan lagi (tentangnya, akan tetapi kebanyakan manusia tidak beriman) kepadanya.",[["إِنَّ","Sesungguhnya"],["ٱلسَّاعَةَ","Jam itu"],["لَـَٔاتِيَةٌۭ","(ada) pasti datang"],["لَّا","tidak"],["رَيْبَ","keraguan"],["فِيهَا","di dalamnya"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"4193":["(Dan Rabb kalian berfirman, \"Berdoalah kepada-Ku, niscaya akan Kuperkenankan bagi kalian) maksudnya, sembahlah Aku, niscaya Aku akan memberi pahala kepada kalian. Pengertian ini disimpulkan dari ayat selanjutnya, yaitu, (Sesungguhnya orang-orang yang menyombongkan diri dari menyembah-Ku akan masuk) dapat dibaca Sayadkhuluuna atau Sayudkhaluuna, menurut bacaan yang kedua artinya, mereka akan dimasukkan ke dalam (neraka Jahanam dalam keadaan hina dina\") dalam keadaan terhina.",[["وَقَالَ","Dan berkata"],["رَبُّكُمُ","Tuhanmu"],["ٱدْعُونِىٓ","Panggillah Aku"],["أَسْتَجِبْ","aku akan balas"],["لَكُمْ ۚ","kepada kamu"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَسْتَكْبِرُونَ","(berbangga)."],["عَنْ","kepada"],["عِبَادَتِى","sembahlah Aku"],["سَيَدْخُلُونَ","akan masuk"],["جَهَنَّمَ","Neraka"],["دَاخِرِينَ","(dalam) penghinaan"]]],"4194":["(Allahlah yang menjadikan malam untuk kalian supaya kalian beristirahat padanya; dan menjadikan siang terang-benderang) dikaitkannya pengertian melihat kepada siang hanyalah majaz atau kata kiasan belaka, karena pada siang hari manusia dapat melihat. (Sesungguhnya Allah benar-benar mempunyai karunia yang dilimpahkan atas manusia, akan tetapi kebanyakan manusia tidak bersyukur) kepada Allah, malahan mereka tidak beriman kepada-Nya.",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلَّيْلَ","malam"],["لِتَسْكُنُوا۟","supaya kamu boleh berehat"],["فِيهِ","di dalamnya"],["وَٱلنَّهَارَ","dan hari"],["مُبْصِرًا ۚ","memberi keterlihatan"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَذُو","(adalah) Penuh (dengan) Bounty"],["فَضْلٍ","(adalah) Penuh (dengan) Bounty"],["عَلَى","kepada"],["ٱلنَّاسِ","manusia"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يَشْكُرُونَ","bersyukurlah"]]],"4195":["(Yang demikian itu adalah Allah, Rabb kalian, Pencipta segala sesuatu, tiada Tuhan melainkan Dia, maka bagaimanakah kalian dapat dipalingkan?) maksudnya, bagaimanakah kalian dipalingkan dari iman kepada-Nya, padahal bukti-bukti-Nya sudah jelas.",[["ذَٰلِكُمُ","Itu"],["ٱللَّهُ","(ialah) Allah"],["رَبُّكُمْ","Tuhanmu"],["خَـٰلِقُ","(the) Pencipta"],["كُلِّ","(dari) semua"],["شَىْءٍۢ","benda"],["لَّآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["فَأَنَّىٰ","Jadi bagaimana"],["تُؤْفَكُونَ","adakah kamu tertipu"]]],"4196":["(Seperti demikianlah dipalingkan) artinya sebagaimana mereka dipalingkan, maka dipalingkan pula (orang-orang yang terhadap ayat-ayat Allah) yakni mukjizat-mukjizat-Nya (mereka ingkar.)",[["كَذَٰلِكَ","Demikianlah"],["يُؤْفَكُ","telah tertipu"],["ٱلَّذِينَ","orang yang"],["كَانُوا۟","adalah"],["بِـَٔايَـٰتِ","(the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["يَجْحَدُونَ","menolak"]]],"4197":["(Allahlah yang menjadikan bumi bagi kalian sebagai tempat menetap dan langit sebagai atap) maksudnya, yang menaungi (dan membentuk kalian lalu membaguskan rupa kalian serta memberi kalian rezeki dengan sebagian yang baik-baik. Yang demikian itu adalah Allah Rabb kalian, Maha Agung Allah, Rabb semesta Alam.)",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلْأَرْضَ","bumi"],["قَرَارًۭا","tempat penempatan"],["وَٱلسَّمَآءَ","dan langit"],["بِنَآءًۭ","sebuah kanopi"],["وَصَوَّرَكُمْ","dan Dia membentuk kamu"],["فَأَحْسَنَ","dan disempurnakan"],["صُوَرَكُمْ","borang kamu"],["وَرَزَقَكُم","dan memberi rezeki kepada kamu"],["مِّنَ","daripada"],["ٱلطَّيِّبَـٰتِ ۚ","perkara yang baik"],["ذَٰلِكُمُ","Itu"],["ٱللَّهُ","(ialah) Allah"],["رَبُّكُمْ ۖ","Tuhanmu"],["فَتَبَارَكَ","Maka diberkati (adalah)"],["ٱللَّهُ","Allah"],["رَبُّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"4198":["(Dialah Yang hidup kekal tiada Tuhan melainkan Dia, maka serulah Dia) sembahlah Dia (dengan memurnikan ibadah kepada-Nya) dari kemusyrikan. (Segala puji bagi Allah Rabb semesta alam.)",[["هُوَ","Dia"],["ٱلْحَىُّ","(ialah) Yang Hidup Kekal"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","tetapi"],["هُوَ","Dia"],["فَٱدْعُوهُ","maka panggillah Dia"],["مُخْلِصِينَ","(bersifat) ikhlas"],["لَهُ","kepada-Nya"],["ٱلدِّينَ ۗ","(dalam) agama"],["ٱلْحَمْدُ","Segala puji (semoga)"],["لِلَّهِ","kepada Allah"],["رَبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"4199":["(Katakanlah, \"Sesungguhnya aku dilarang menyembah sesembahan yang kalian seru) yang kalian sembah (selain Allah setelah datang kepadaku keterangan-keterangan) yakni bukti-bukti tauhid (dari Rabbku, dan aku diperintahkan supaya tunduk patuh kepada Rabb semesta alam.)",[["۞ قُلْ","Katakanlah"],["إِنِّى","Sesungguhnya aku"],["نُهِيتُ","[Aku] telah dilarang"],["أَنْ","kepada"],["أَعْبُدَ","ibadah"],["ٱلَّذِينَ","mereka yang"],["تَدْعُونَ","kamu panggil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["لَمَّا","apabila"],["جَآءَنِىَ","telah datang kepada aku"],["ٱلْبَيِّنَـٰتُ","bukti-bukti yang jelas"],["مِن","daripada"],["رَّبِّى","Tuhanku"],["وَأُمِرْتُ","dan aku diperintahkan"],["أَنْ","kepada"],["أُسْلِمَ","menyerahkan"],["لِرَبِّ","kepada (Tuhan)."],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"4200":["(Dialah Yang menciptakan kalian dari tanah) yang menciptakan bapak moyang kalian yaitu Nabi Adam dari tanah liat (kemudian dari setetes nuthfah) yakni air mani (sesudah itu dari segumpal darah) yakni dari kental (kemudian dikeluarkan-Nya kalian sebagai seorang anak) lafal Thiflan sekalipun bentuknya mufrad atau tunggal, bermakna jamak (kemudian) dibiarkan-Nya kalian hidup (supaya kalian sampai kepada masa dewasa) masa sempurnanya kekuatan kalian, yaitu di antara umur tiga puluh sampai dengan empat puluh tahun (kemudian -dibiarkan-Nya kalian hidup- sampai tua) dapat dibaca Syuyuukhan atau Syiyuukhan (di antara kalian ada yang diwafatkan sebelum itu) sebelum dewasa dan sebelum mencapai usia tua. Dia melakukan hal tersebut kepada kalian supaya kalian hidup (dan supaya kalian sampai pada ajal yang ditentukan) yakni waktu yang telah dibataskan bagi hidup kalian (dan supaya kalian memahami) bukti-bukti yang menunjukkan keesaan-Nya, kemudian kalian beriman kepada-Nya.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَكُم","mencipta kamu"],["مِّن","daripada"],["تُرَابٍۢ","habuk"],["ثُمَّ","kemudian"],["مِن","daripada"],["نُّطْفَةٍۢ","titisan air mani"],["ثُمَّ","kemudian"],["مِنْ","daripada"],["عَلَقَةٍۢ","bahan yang melekat"],["ثُمَّ","kemudian"],["يُخْرِجُكُمْ","Dia membawa kamu keluar"],["طِفْلًۭا","(sebagai) kanak-kanak"],["ثُمَّ","kemudian"],["لِتَبْلُغُوٓا۟","membolehkan kamu mencapai"],["أَشُدَّكُمْ","kematangan kamu"],["ثُمَّ","kemudian"],["لِتَكُونُوا۟","membolehkan kamu menjadi"],["شُيُوخًۭا ۚ","lama"],["وَمِنكُم","dan di antara kamu"],["مَّن","(adakah dia) siapa"],["يُتَوَفَّىٰ","mati"],["مِن","sebelum ini"],["قَبْلُ ۖ","sebelum ini"],["وَلِتَبْلُغُوٓا۟","dan membolehkan kamu mencapai"],["أَجَلًۭا","satu istilah"],["مُّسَمًّۭى","ditentukan"],["وَلَعَلَّكُمْ","dan supaya kamu boleh"],["تَعْقِلُونَ","guna akal"]]],"4201":["(Dialah yang menghidupkan dan yang mematikan, maka apabila Dia menetapkan sesuatu urusan) artinya, Dia berkehendak mewujudkan sesuatu (Dia hanya berkata kepadanya, 'Jadilah!' maka jadilah ia.\") lafal Fayakuunu dapat pula dibaca Fayakuuna akan tetapi dengan memperkirakan adanya huruf An sebelumnya. Yakni, sesuatu yang dikehendaki itu langsung ada sesudah ada kehendak-Nya, sebagaimana yang telah digambarkan oleh makna firman yang tadi itu.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["يُحْىِۦ","memberi kehidupan"],["وَيُمِيتُ ۖ","dan menyebabkan kematian"],["فَإِذَا","Dan apabila"],["قَضَىٰٓ","Dia menetapkan"],["أَمْرًۭا","sesuatu perkara"],["فَإِنَّمَا","kemudian sahaja"],["يَقُولُ","Dia berkata"],["لَهُۥ","kepadanya"],["كُن","Jadilah"],["فَيَكُونُ","dan ia adalah"]]],"4202":["(Apakah kamu tidak melihat kepada orang-orang yang membantah ayat-ayat Allah?) membantah Alquran. (Bagaimanakah) (mereka dapat dipalingkan) dari iman?",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["إِلَى","[ke]"],["ٱلَّذِينَ","orang yang"],["يُجَـٰدِلُونَ","pertikaian"],["فِىٓ","tentang"],["ءَايَـٰتِ","(the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["أَنَّىٰ","Bagaimana"],["يُصْرَفُونَ","mereka berpaling"]]],"4203":["(Orang-orang yang mendustakan Alkitab) yakni Al-Qur'an (dan wahyu yang dibawa oleh rasul-rasul Kami yang telah Kami utus) dengan membawa ajaran tauhid dan berita tentang adanya hari berbangkit; mereka adalah orang-orang kafir Mekah. (Kelak mereka akan mengetahui) akibat dari kedustaan mereka.",[["ٱلَّذِينَ","Orang yang"],["كَذَّبُوا۟","menafikan"],["بِٱلْكِتَـٰبِ","Kitab"],["وَبِمَآ","dan dengan apa"],["أَرْسَلْنَا","Kami utus"],["بِهِۦ","dengannya"],["رُسُلَنَا ۖ","Rasul-rasul Kami"],["فَسَوْفَ","tetapi tidak lama lagi"],["يَعْلَمُونَ","mereka akan tahu"]]],"4204":["(Ketika belenggu dipasang di leher mereka) lafal Idz di sini bermakna Idzaa yakni ketika (dan rantai-rantai) pun dipasang pula di leher mereka. Lafal As-Salaasilu ini diathafkan kepada lafal Al-Aghlaalu. Atau berkedudukan menjadi Mubtada sedangkan Khabarnya tidak disebutkan, yaitu lafal Fii Arjulihim. Dengan demikian maka artinya ialah, Dan rantai-rantai pun dipasang pada kaki mereka Atau Khabar lafal As-Salaasilu ini ialah ayat berikutnya, yaitu (seraya mereka diseret) dengannya.",[["إِذِ","Apabila"],["ٱلْأَغْلَـٰلُ","kolar besi"],["فِىٓ","(akan ada) di sekeliling"],["أَعْنَـٰقِهِمْ","leher mereka"],["وَٱلسَّلَـٰسِلُ","dan rantai"],["يُسْحَبُونَ","mereka akan diseret"]]],"4205":["(Ke dalam air yang sangat panas) yakni neraka Jahanam (kemudian mereka dibakar dalam api) maksudnya, mereka dibakar oleh api neraka.",[["فِى","Dalam"],["ٱلْحَمِيمِ","air mendidih"],["ثُمَّ","kemudian"],["فِى","dalam"],["ٱلنَّارِ","neraka"],["يُسْجَرُونَ","mereka akan dibakar"]]],"4206":["(Kemudian dikatakan kepada mereka) sebagai celaan dan penelanjangan, (\"Manakah berhala-berhala yang selalu kalian persekutukan?)",[["ثُمَّ","Kemudian"],["قِيلَ","ia akan dikatakan"],["لَهُمْ","kepada mereka"],["أَيْنَ","di mana"],["مَا","(ialah) yang"],["كُنتُمْ","kamu pernah"],["تُشْرِكُونَ","bersekutu"]]],"4207":["(Selain Allah?\") yang kalian sembah selain-Nya; yang dimaksud adalah berhala-berhala. (Mereka menjawab, \"Mereka telah hilang lenyap) artinya, telah tiada (dari kami) maka kami tidak melihat mereka (bahkan kami dahulu tiada pernah menyembah sesuatu\") mereka mengingkari penyembahan mereka kepada berhala-berhala itu. Kemudian berhala-berhala sesembahan mereka itu didatangkan, selanjutnya dikatakan kepada mereka, sebagaimana yang disebutkan dalam ayat yang lain, yaitu firman-Nya, \"Sesungguhnya kalian dan apa yang kalian sembah selain Allah, adalah makanan Jahanam.\" (Q.S. Al-Anbiya, 98). (Seperti demikianlah) yakni sebagaimana disesatkan-Nya orang-orang yang mendustakan Alquran (Allah menyesatkan orang-orang kafir.)",[["مِن","Selain daripada"],["دُونِ","Selain daripada"],["ٱللَّهِ ۖ","Allah"],["قَالُوا۟","Mereka akan berkata"],["ضَلُّوا۟","Mereka telah berlepas"],["عَنَّا","daripada kami"],["بَل","Bahkan"],["لَّمْ","Tidak"],["نَكُن","kita dulu"],["نَّدْعُوا۟","[kami] memanggil"],["مِن","sebelum"],["قَبْلُ","sebelum"],["شَيْـًۭٔا ۚ","sesuatu"],["كَذَٰلِكَ","Demikianlah"],["يُضِلُّ","Allah biarkan sesat"],["ٱللَّهُ","Allah biarkan sesat"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"4208":["Dikatakan pula kepada mereka, (\"Yang demikian itu) yakni azab itu (disebabkan kalian bersuka ria di muka bumi dengan tidak benar) yaitu melakukan perbuatan syirik dan ingkar kepada adanya hari berbangkit (dan karena kalian selalu bersuka ria) artinya, terlalu berlebih-lebihan di dalam bersuka ria.",[["ذَٰلِكُم","Itu tadi"],["بِمَا","kerana"],["كُنتُمْ","kamu pernah"],["تَفْرَحُونَ","bergembiralah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ","betul"],["وَبِمَا","dan kerana"],["كُنتُمْ","kamu pernah"],["تَمْرَحُونَ","bersikap kurang ajar"]]],"4209":["(Masuklah kalian ke pintu-pintu neraka Jahanam, sedangkan kalian kekal di dalamnya. Maka itulah seburuk-buruk tempat) yakni tempat tinggal (bagi orang-orang yang sombong.\")",[["ٱدْخُلُوٓا۟","Masuk"],["أَبْوَٰبَ","(the) pintu gerbang"],["جَهَنَّمَ","(dari) Neraka"],["خَـٰلِدِينَ","(untuk) kekal selama-lamanya"],["فِيهَا ۖ","di dalamnya"],["فَبِئْسَ","dan celaka adalah"],["مَثْوَى","(tempat tinggal)."],["ٱلْمُتَكَبِّرِينَ","(dari) orang yang sombong"]]],"4210":["(Maka bersabarlah kamu, sesungguhnya janji Allah) yang akan mengazab mereka (adalah benar; maka jika Kami perlihatkan kepadamu) lafal Immaa adalah berasal dari In Syarthiyah yang diidgamkan kepada Maa Zaidah yang berfungsi mengukuhkan makna Syarat di awal Fi'il, kemudian menyusul Nun Taukid sesudahnya yang juga mengukuhkan makna syarath tadi (sebagian siksa yang Kami ancamkan kepada mereka) yakni semasa kamu masih hidup Kami menurunkan sebagian azab kepada mereka. Jawab Syarathnya tidak disebutkan, yaitu lafal Fadzaaka, yakni maka itulah sebagian dari azab Kami (atau pun Kami wafatkan kamu) yaitu sebelum mereka diazab (namun kepada Kami sajalah mereka dikembalikan) lalu Kami akan mengazab mereka dengan siksaan yang sangat keras. Jawab Syarath yang telah disebutkan di atas tadi hanyalah untuk Ma'thuf saja, yakni hanya untuk kalimah, Fa-immaa Nuriyannaka Ba'dhal Ladzii Na'iduhum, Fadzaaka.",[["فَٱصْبِرْ","Jadi bersabarlah"],["إِنَّ","sesungguhnya"],["وَعْدَ","(the) Janji"],["ٱللَّهِ","(milik) Allah"],["حَقٌّۭ ۚ","(adalah) benar"],["فَإِمَّا","Dan sama ada"],["نُرِيَنَّكَ","Kami tunjukkan kepada kamu"],["بَعْضَ","beberapa"],["ٱلَّذِى","apa"],["نَعِدُهُمْ","Kami telah berjanji kepada mereka"],["أَوْ","atau"],["نَتَوَفَّيَنَّكَ","Kami menyebabkan kamu mati"],["فَإِلَيْنَا","kemudian kepada Kami"],["يُرْجَعُونَ","mereka akan dikembalikan"]]],"4211":["(Dan sesungguhnya telah Kami utus rasul-rasul sebelum kamu; di antara mereka ada yang Kami ceritakan kepadamu dan di antara mereka ada -pula- yang tidak Kami ceritakan kepadamu) menurut suatu riwayat diceritakan, bahwa Allah swt. telah mengutus delapan ribu orang nabi untuk menjadi rasul; yang empat ribu orang di antaranya dari kaum Bani Israel, sedangkan yang empat ribu orang lagi dari kalangan umat-umat selain Bani Israel. (Tidak dapat bagi seorang rasul) di antara rasul-rasul itu (membawa suatu mukjizat, melainkan dengan seizin Allah) karena mereka juga hamba-hamba Allah yang diperintah oleh-Nya (maka apabila telah datang perintah Allah) yang memerintahkan supaya azab diturunkan atas orang-orang kafir (diputuskan) semua perkara di antara rasul-rasul dan orang-orang yang mendustakannya (dengan adil. Dan ketika itu rugilah orang-orang yang berpegang kepada yang batil) yakni, keputusan itu merupakan kemenangan bagi rasul-rasul dan kerugian bagi orang-orang yang mendustakannya; pada hakikatnya sebelum itu pun orang-orang yang mendustakan para rasul sudah merugi.",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَا","Kami telah menghantar"],["رُسُلًۭا","Utusan"],["مِّن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["مِنْهُم","Antaranya"],["مَّن","(adalah) siapa"],["قَصَصْنَا","Kami ada kaitan"],["عَلَيْكَ","kepada kamu"],["وَمِنْهُم","dan antara mereka"],["مَّن","(adalah) siapa"],["لَّمْ","tidak"],["نَقْصُصْ","Kami ada kaitan"],["عَلَيْكَ ۗ","kepada kamu"],["وَمَا","Dan tidak"],["كَانَ","ialah"],["لِرَسُولٍ","untuk mana-mana Rasul"],["أَن","bahawa"],["يَأْتِىَ","dia bawak"],["بِـَٔايَةٍ","sebuah Tanda"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan izin (yang)"],["ٱللَّهِ ۚ","(milik) Allah"],["فَإِذَا","Maka apabila"],["جَآءَ","datang"],["أَمْرُ","(the) Perintah"],["ٱللَّهِ","(milik) Allah"],["قُضِىَ","ia akan diputuskan"],["بِٱلْحَقِّ","dalam kebenaran"],["وَخَسِرَ","dan akan kalah"],["هُنَالِكَ","di sana"],["ٱلْمُبْطِلُونَ","para pemalsu"]]],"4212":["(Allahlah yang menjadikan binatang ternak untuk kalian) menurut suatu pendapat dikatakan, bahwa yang dimaksud hanyalah unta saja. Tetapi menurut pendapat yang kuat, ternak yang dimaksud mencakup pula sapi dan kambing (sebagiannya untuk kalian kendarai dan sebagiannya untuk kalian makan.)",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلْأَنْعَـٰمَ","lembu itu"],["لِتَرْكَبُوا۟","yang boleh kamu tunggangi"],["مِنْهَا","sebahagian mereka"],["وَمِنْهَا","dan sebahagian daripada mereka"],["تَأْكُلُونَ","kamu makan"]]],"4213":["(Dan -ada lagi- manfaat-manfaat lain pada binatang ternak itu untuk kalian) yaitu berupa air susu, keturunan binatang ternak itu dan juga dari bulu-bulunya (dan supaya kalian mencapai suatu keperluan yang tersimpan dalam hati) maksudnya, dapat kalian gunakan untuk mengangkut barang-barang ke berbagai negeri (dengan mengendarainya) di daratan (dan dengan menaiki bahtera) yakni perahu melalui jalan laut (kalian dapat menaiki semuanya.)",[["وَلَكُمْ","Dan untuk kamu"],["فِيهَا","dalam diri mereka"],["مَنَـٰفِعُ","(adalah) faedah"],["وَلِتَبْلُغُوا۟","dan supaya kamu dapat mencapainya"],["عَلَيْهَا","melalui mereka"],["حَاجَةًۭ","satu keperluan"],["فِى","(iaitu) dalam"],["صُدُورِكُمْ","buah dada kamu"],["وَعَلَيْهَا","dan atas mereka"],["وَعَلَى","dan seterusnya"],["ٱلْفُلْكِ","kapal-kapal itu"],["تُحْمَلُونَ","kamu dibawa"]]],"4214":["(Dan Dia memperlihatkan kepada kalian tanda-tanda-Nya; maka tanda-tanda Allah yang manakah) yakni tanda-tanda yang menunjukkan kepada keesaan-Nya (yang kalian ingkari?) Istifham atau kata tanya di sini mengandung makna cemoohan. Disebutkan lafal Ayyun dalam bentuk Mudzakkar adalah lebih terkenal daripada bentuk Ta'nitsnya.",[["وَيُرِيكُمْ","Dan Dia menunjukkan kepada kamu"],["ءَايَـٰتِهِۦ","Tanda-tandaNya"],["فَأَىَّ","Kemudian yang mana"],["ءَايَـٰتِ","(dari) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["تُنكِرُونَ","adakah kamu akan menafikan"]]],"4215":["(Maka apakah mereka tiada mengadakan perjalanan di muka bumi lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Adalah orang-orang yang sebelum mereka itu lebih hebat kekuatannya dan -lebih banyak- bekas-bekas mereka di muka bumi) seperti gedung-gedung dan bangunan-bangunan lainnya sebagai peninggalan mereka (maka apa yang mereka usahakan itu tidak dapat menolong mereka.)",[["أَفَلَمْ","Adakah mereka tidak"],["يَسِيرُوا۟","melancong"],["فِى","melalui"],["ٱلْأَرْضِ","bumi"],["فَيَنظُرُوا۟","dan lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ ۚ","(ada) sebelum mereka"],["كَانُوٓا۟","Mereka"],["أَكْثَرَ","lebih ramai"],["مِنْهُمْ","daripada mereka"],["وَأَشَدَّ","dan lebih perkasa"],["قُوَّةًۭ","(dalam) kekuatan"],["وَءَاثَارًۭا","dan tanggapan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَمَآ","tetapi tidak"],["أَغْنَىٰ","dimanfaatkan"],["عَنْهُم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["يَكْسِبُونَ","peroleh"]]],"4216":["(Maka tatkala datang kepada mereka rasul-rasul mereka dengan membawa keterangan-keterangan) yakni mukjizat-mukjizat yang nyata (mereka merasa senang) orang-orang kafir itu (dengan apa yang ada pada mereka) yakni rasul-rasul itu (yaitu pengetahuan mereka) pengertian gembira di sini mengandung makna ejekan dan olok-olokan seraya ingkar kepada apa yang didatangkan oleh para rasul itu (dan menimpalah) maksudnya, turunlah (kepada mereka apa yang selalu mereka perolok-olokkan itu) yaitu, azab Allah yang selalu mereka ejek itu.",[["فَلَمَّا","Kemudian apabila"],["جَآءَتْهُمْ","datang kepada mereka"],["رُسُلُهُم","Rasul-rasul mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَرِحُوا۟","mereka bergembira"],["بِمَا","pada apa"],["عِندَهُم","mereka telah"],["مِّنَ","daripada"],["ٱلْعِلْمِ","pengetahuan itu"],["وَحَاقَ","dan diselubungi"],["بِهِم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["بِهِۦ","[padanya]"],["يَسْتَهْزِءُونَ","mengejek"]]],"4217":["(Maka tatkala mereka melihat azab Kami) yakni betapa kerasnya azab Kami (mereka berkata, \"Kami beriman hanya kepada Allah saja, dan kami kafir kepada sesembahan-sesembahan yang telah kami mempersekutukannya dengan Allah.\")",[["فَلَمَّا","Maka apabila"],["رَأَوْا۟","mereka nampak"],["بَأْسَنَا","hukuman kita"],["قَالُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami beriman"],["بِٱللَّهِ","kepada Allah"],["وَحْدَهُۥ","bersendirian"],["وَكَفَرْنَا","dan kami kufur"],["بِمَا","pada apa"],["كُنَّا","kita dulu"],["بِهِۦ","dengan Dia"],["مُشْرِكِينَ","bersekutu"]]],"4218":["(Maka iman mereka tiada berguna bagi mereka tatkala mereka telah melihat siksa Kami. Itulah sunah Allah) dinashabkannya lafal Sunnatallaahi karena menjadi Mashdar dari Fi'il yang diperkirakan keberadaannya, dan Fi'il tersebut diambil dari lafalnya (yang telah berlaku terhadap hamba-hamba-Nya) yaitu pada semua umat, bahwasanya iman tiada gunanya apabila timbul di kala azab turun. (Dan di waktu itu merugilah orang-orang kafir) yakni jelaslah kerugian mereka; masing-masing di antara mereka mengalami kerugian yang nyata; dan memang sebelum itu pun mereka adalah orang-orang yang merugi.",[["فَلَمْ","Tetapi tidak"],["يَكُ","Tetapi tidak"],["يَنفَعُهُمْ","memberi manfaat kepada mereka"],["إِيمَـٰنُهُمْ","iman mereka"],["لَمَّا","apabila"],["رَأَوْا۟","mereka nampak"],["بَأْسَنَا ۖ","hukuman kita"],["سُنَّتَ","(Begitulah) Jalan"],["ٱللَّهِ","(milik) Allah"],["ٱلَّتِى","yang"],["قَدْ","(mempunyai) sesungguhnya"],["خَلَتْ","didahulukan"],["فِى","antara"],["عِبَادِهِۦ ۖ","hambanya"],["وَخَسِرَ","Dan hilang"],["هُنَالِكَ","di sana"],["ٱلْكَـٰفِرُونَ","orang kafir"]]],"4219":["(Haa Miim) hanya Allah saja yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Mim"]]],"4220":["(Diturunkan dari Tuhan Yang Maha Pemurah lagi Maha Penyayang) kalimat ayat ini berkedudukan menjadi Mubtada.",[["تَنزِيلٌۭ","Satu wahyu"],["مِّنَ","daripada"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["ٱلرَّحِيمِ","Yang Maha Mengasihani"]]],"4221":["(Kitab) lafal ayat ini menjadi Khabar Mubtada (yang dijelaskan ayat-ayatnya) maksudnya, dijelaskan di dalamnya hukum-hukum, kisah-kisah dan nasihat-nasihat (yakni bacaan dalam bahasa Arab) lafal Qur-aanan berikut sifatnya menjadi Haal atau kata keterangan keadaan dari lafal Kitaabun (untuk kaum) berta'alluq kepada lafal Fushshilat (yang mengetahui) artinya, bagi mereka yang mengerti, yaitu orang-orang Arab.",[["كِتَـٰبٌۭ","Sebuah Buku"],["فُصِّلَتْ","adalah terperinci"],["ءَايَـٰتُهُۥ","Ayat-ayatnya"],["قُرْءَانًا","sebuah Al-Quran"],["عَرَبِيًّۭا","(dalam) bahasa Arab"],["لِّقَوْمٍۢ","bagi kaum"],["يَعْلَمُونَ","(siapa) tahu"]]],"4222":["(Yang membawa berita gembira) menjadi sifat dari lafal Qur-aanan (dan yang membawa peringatan, tetapi kebanyakan mereka berpaling darinya maka mereka tidak mau mendengarkan) dengan pendengaran yang terdorong oleh perasaan mau menerima apa yang didengarnya.",[["بَشِيرًۭا","Seorang pemberi khabar gembira"],["وَنَذِيرًۭا","dan pemberi amaran"],["فَأَعْرَضَ","tetapi berpaling"],["أَكْثَرُهُمْ","kebanyakan mereka"],["فَهُمْ","jadi mereka"],["لَا","jangan"],["يَسْمَعُونَ","dengar"]]],"4223":["(Mereka berkata) kepada Nabi saw., (\"Hati kami berada dalam tutupan) tertutup dari (apa yang kamu seru kami kepadanya dan di telinga kami ada sumbatan) yakni penutup (dan di antara kami dan kamu ada dinding) pemisah dalam masalah agama (maka bekerjalah kamu) sesuai dengan tuntunan agamamu (sesungguhnya kami bekerja pula\") sesuai dengan tuntunan agama kami.",[["وَقَالُوا۟","Dan mereka berkata"],["قُلُوبُنَا","hati kita"],["فِىٓ","(ada) dalam"],["أَكِنَّةٍۢ","penutup"],["مِّمَّا","daripada apa"],["تَدْعُونَآ","kamu hubungi kami"],["إِلَيْهِ","kepadanya"],["وَفِىٓ","dan dalam"],["ءَاذَانِنَا","telinga kita"],["وَقْرٌۭ","(adalah) pekak"],["وَمِنۢ","dan antara kita"],["بَيْنِنَا","dan antara kita"],["وَبَيْنِكَ","dan antara kamu"],["حِجَابٌۭ","(ialah) skrin"],["فَٱعْمَلْ","Jadi kerja"],["إِنَّنَا","sesungguhnya, kita"],["عَـٰمِلُونَ","(sedang) bekerja"]]],"4224":["(Katakanlah, \"Bahwasanya aku hanyalah seorang manusia seperti kalian, diwahyukan kepadaku bahwasanya Tuhan kalian adalah Tuhan Yang Maha Esa, maka tetaplah pada jalan yang lurus menuju kepada-Nya) yakni dengan beriman dan taat kepada-Nya (dan mohonlah ampun kepada-Nya. Dan kecelakaan yang besarlah) lafal Al-Wail ini merupakan kalimat azab (bagi orang-orang yang musyrik.)",[["قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أَنَا۠","aku"],["بَشَرٌۭ","seorang lelaki"],["مِّثْلُكُمْ","macam kamu"],["يُوحَىٰٓ","ia didedahkan"],["إِلَىَّ","kepada aku"],["أَنَّمَآ","bahawa"],["إِلَـٰهُكُمْ","tuhan kamu"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ","satu"],["فَٱسْتَقِيمُوٓا۟","jadi ambillah Jalan Yang Lurus"],["إِلَيْهِ","kepada-Nya"],["وَٱسْتَغْفِرُوهُ ۗ","dan memohon ampun kepada-Nya"],["وَوَيْلٌۭ","Dan celaka"],["لِّلْمُشْرِكِينَ","kepada orang musyrik"]]],"4225":["(Yaitu orang-orang yang tidak menunaikan zakat dan mereka kepada kehidupan akhirat benar-benar mereka) Hum yang kedua ini mengandung makna mengukuhkan lafal Hum yang pertama (kafir.)",[["ٱلَّذِينَ","Orang yang"],["لَا","jangan"],["يُؤْتُونَ","memberi"],["ٱلزَّكَوٰةَ","zakat tersebut"],["وَهُم","dan mereka"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["هُمْ","mereka"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"4226":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal yang saleh mereka mendapat pahala yang tiada putus-putusnya\") tanpa henti-hentinya.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["لَهُمْ","bagi mereka"],["أَجْرٌ","(adalah) ganjaran"],["غَيْرُ","tidak pernah berakhir"],["مَمْنُونٍۢ","tidak pernah berakhir"]]],"4227":["(Katakanlah, \"Sesungguhnya patutkah kalian) kedua huruf Hamzah pada lafal A-innakum dapat dibaca Tahqiq dan dapat pula dibaca Tas-hil (kafir kepada Yang menciptakan bumi dalam dua hari) yaitu hari Ahad dan hari Senin (dan kalian adakan sekutu-sekutu bagi-Nya\") tandingan-tandingan bagi-Nya. (Yang bersifat demikian itulah Rabb) yakni pemilik (semesta alam) lafal Al-Aalamiina adalah bentuk jamak dari lafal Aalamun, maksudnya adalah segala sesuatu yang selain Allah. Kemudian dijamakkan mengingat jenisnya yang bermacam-macam, dan jamak di sini memakai Ya dan Nun karena memprioritaskan makhluk yang berakal.",[["۞ قُلْ","Katakanlah"],["أَئِنَّكُمْ","Adakah kamu memang"],["لَتَكْفُرُونَ","[pasti] kafir"],["بِٱلَّذِى","pada Yang Esa"],["خَلَقَ","dicipta"],["ٱلْأَرْضَ","bumi"],["فِى","dalam"],["يَوْمَيْنِ","dua tempoh"],["وَتَجْعَلُونَ","dan kamu sediakan"],["لَهُۥٓ","dengan Dia"],["أَندَادًۭا ۚ","saingan"],["ذَٰلِكَ","Itu"],["رَبُّ","(ialah) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"4228":["(Dan Dia menjadikan) merupakan jumlah Istinaf, dan tidak boleh di'athafkan kepada Shilah Al-Ladzii karena ada pemisah yang bersifat Ajnabii yaitu ayat, Wataj'aluuna Lahuu Andaadan dan seterusnya (di bumi itu gunung-gunung) yang kokoh dan kuat (di atasnya dan Dia memberkahinya) dengan air yang banyak, dan tanam-tanaman serta pohon-pohon yang banyak pula (dan Dia menentukan) artinya, membagi-bagikan (padanya kadar makanan-makanannya) untuk manusia dan fauna (dalam) masa penjadian yang sempurna yaitu (empat hari) hal ini dijadikan-Nya pada hari Selasa dan Rabu (yang genap) dinashabkan karena menjadi Mashdar, maksudnya penciptaan itu selama empat hari genap; tidak bertambah dan tidak pula berkurang dari itu (bagi orang-orang yang bertanya) maksudnya, sebagai jawaban bagi orang-orang yang menanyakan tentang penciptaan bumi dan segala isinya.",[["وَجَعَلَ","Dan Dia meletakkan"],["فِيهَا","di dalamnya"],["رَوَٰسِىَ","gunung yang tersusun kukuh"],["مِن","di atasnya"],["فَوْقِهَا","di atasnya"],["وَبَـٰرَكَ","dan Dia memberkati"],["فِيهَا","di dalamnya"],["وَقَدَّرَ","dan berazam"],["فِيهَآ","di dalamnya"],["أَقْوَٰتَهَا","rezekinya"],["فِىٓ","dalam"],["أَرْبَعَةِ","empat"],["أَيَّامٍۢ","tempoh"],["سَوَآءًۭ","sama rata"],["لِّلسَّآئِلِينَ","bagi yang bertanya"]]],"4229":["(Kemudian Dia menuju) bermaksud kepada (penciptaan langit dan langit itu masih merupakan asap) masih berbentuk asap yang membumbung tinggi (lalu Dia berfirman kepadanya dan kepada bumi, \"Datanglah kamu keduanya) menurut perintah-Ku (dengan suka hati atau terpaksa\") kedua lafal ini berkedudukan sama dengan Hal, yakni baik dalam keadaan senang hati atau terpaksa (keduanya menjawab, \"Kami datang) beserta makhluk yang ada pada kami (dengan suka hati\") di dalam ungkapan ini diprioritaskan Dhamir Mudzakkar lagi Aqil; atau khithab kepada keduanya disamakan dengan jamak.",[["ثُمَّ","Kemudian"],["ٱسْتَوَىٰٓ","Dia mengarahkan (Sendiri)"],["إِلَى","ke arah"],["ٱلسَّمَآءِ","syurga itu"],["وَهِىَ","semasa itu (adalah)"],["دُخَانٌۭ","asap"],["فَقَالَ","dan Dia berkata"],["لَهَا","kepadanya"],["وَلِلْأَرْضِ","dan ke bumi"],["ٱئْتِيَا","Datanglah kamu berdua"],["طَوْعًا","dengan rela hati"],["أَوْ","atau"],["كَرْهًۭا","tanpa rela"],["قَالَتَآ","Mereka berdua berkata"],["أَتَيْنَا","Kami datang"],["طَآئِعِينَ","dengan rela hati"]]],"4230":["(Maka Dia menjadikannya) dhamir yang ada pada lafal ayat ini kembali kepada lafal As-Samaa atau langit, karena memandang dari segi maknanya (tujuh langit dalam dua hari) yakni hari Kamis dan hari Jumat, Dia telah selesai dari menciptakan langit pada saat-saat terakhir dari hari tersebut. Dan pada hari itu juga diciptakan Nabi Adam, oleh karena itu maka di sini tidak dikatakan Fasawwaahunna tetapi Faqadhaahunna. Dan sesuai dengan makna ayat ini yaitu ayat-ayat tentang penciptaan langit dan bumi dalam enam hari (dan Dia mewahyukan pada tiap-tiap langit urusannya) yang telah Dia perintahkan kepada penduduk yang ada di dalamnya, yaitu taat dan beribadah kepada-Nya. (Dan Kami hiasi langit yang dekat dengan pelita-pelita) yakni bintang-bintang yang cemerlang (dan Kami memeliharanya) dinashabkan oleh Fi'ilnya yang keberadaannya diperkirakan, Kami menjaganya dengan meteor-meteor dari setan yang mau mencuri-curi pembicaraan para malaikat. (Demikianlah ketentuan Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Mengetahui) makhluk-Nya.",[["فَقَضَىٰهُنَّ","Kemudian Dia menyempurnakan mereka"],["سَبْعَ","(sebagai) tujuh"],["سَمَـٰوَاتٍۢ","syurga"],["فِى","dalam"],["يَوْمَيْنِ","dua tempoh"],["وَأَوْحَىٰ","dan Dia mewahyukan"],["فِى","dalam"],["كُلِّ","setiap satu"],["سَمَآءٍ","syurga"],["أَمْرَهَا ۚ","urusannya"],["وَزَيَّنَّا","Dan Kami menghiasi"],["ٱلسَّمَآءَ","syurga itu"],["ٱلدُّنْيَا","[dunia]"],["بِمَصَـٰبِيحَ","dengan lampu"],["وَحِفْظًۭا ۚ","dan (untuk) menjaga"],["ذَٰلِكَ","Itu"],["تَقْدِيرُ","(ialah) Dekri"],["ٱلْعَزِيزِ","(dari) Yang Maha Perkasa"],["ٱلْعَلِيمِ","yang Maha Mengetahui"]]],"4231":["(Jika mereka berpaling) yaitu orang-orang kafir Mekah dari iman sesudah adanya penjelasan ini (maka katakanlah, \"Aku memperingatkan kalian) aku mempertakuti kalian (dengan petir, seperti petir yang menimpa kaum Ad dan kaum Tsamud) yakni dengan azab yang akan membinasakan kalian sama dengan azab yang membinasakan mereka.",[["فَإِنْ","Tetapi jika"],["أَعْرَضُوا۟","mereka berpaling"],["فَقُلْ","kemudian berkata"],["أَنذَرْتُكُمْ","Aku telah memberi amaran kepada kamu"],["صَـٰعِقَةًۭ","(dari) petir"],["مِّثْلَ","suka"],["صَـٰعِقَةِ","(the) petir"],["عَادٍۢ","(daripada) Aad"],["وَثَمُودَ","dan kaum Thamud"]]],"4232":["(Ketika rasul-rasul datang kepada mereka dari depan dan dari belakang mereka) rasul-rasul itu datang kepada mereka dari arah depan dan dari arah belakang, akan tetapi mereka tetap ingkar dan kafir, sebagaimana yang akan dijelaskan nanti. Dan pengertian pembinasaan ini hanya berlaku pada zamannya saja (\"Janganlah kalian menyembah selain Allah. Mereka menjawab, 'Kalau Rabb kami menghendaki tentu Dia menurunkan) kepada kami (malaikat-malaikat-Nya, maka sesungguhnya kami kepada wahyu yang kalian diutus membawanya) sesuai dengan sangkaan kalian itu (adalah orang-orang yang kafir.'\")",[["إِذْ","Apabila"],["جَآءَتْهُمُ","datang kepada mereka"],["ٱلرُّسُلُ","para Rasul"],["مِنۢ","dari hadapan mereka"],["بَيْنِ","dari hadapan mereka"],["أَيْدِيهِمْ","dari hadapan mereka"],["وَمِنْ","dan daripada"],["خَلْفِهِمْ","belakang mereka"],["أَلَّا","(sambil berkata) \"Jangan"],["تَعْبُدُوٓا۟","ibadah"],["إِلَّا","kecuali"],["ٱللَّهَ ۖ","Allah"],["قَالُوا۟","Mereka berkata"],["لَوْ","Jika"],["شَآءَ","(telah) berkehendak"],["رَبُّنَا","Tuhan kami"],["لَأَنزَلَ","sesungguhnya Dia (akan) menurunkan"],["مَلَـٰٓئِكَةًۭ","malaikat"],["فَإِنَّا","Jadi sesungguhnya, kita"],["بِمَآ","pada apa"],["أُرْسِلْتُم","kamu telah dihantar"],["بِهِۦ","dengan"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"4233":["(Adapun kaum Ad maka mereka menyombongkan diri di muka bumi tanpa alasan yang benar dan berkata) ketika mereka diperingatkan dengan azab, (\"Siapakah yang lebih besar kekuatannya dari kami?\") maksudnya, tiada seorang pun yang lebih kuat dari kami. Menurut suatu riwayat disebutkan, bahwa seseorang dari mereka mampu mengangkat batu yang sangat besar dari sebuah gunung, kemudian ia mengolahnya sesuai dengan apa yang dia kehendaki. (Dan apakah mereka tidak memperhatikan) apakah mereka tidak mengetahui (bahwa Allah Yang menciptakan mereka adalah lebih besar kekuatan-Nya dari mereka? Dan bahwasanya mereka terhadap tanda-tanda Kami) yakni mukjizat-mukjizat Kami (adalah orang-orang yang ingkar.)",[["فَأَمَّا","Kemudian untuk"],["عَادٌۭ","Aad"],["فَٱسْتَكْبَرُوا۟","mereka sombong"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ","[yang] betul"],["وَقَالُوا۟","dan mereka berkata"],["مَنْ","Siapa"],["أَشَدُّ","(adalah) lebih kuat"],["مِنَّا","daripada kita"],["قُوَّةً ۖ","(dalam) kekuatan"],["أَوَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["ٱلَّذِى","yang Esa"],["خَلَقَهُمْ","mencipta mereka"],["هُوَ","Dia"],["أَشَدُّ","(adalah) Lebih Perkasa"],["مِنْهُمْ","daripada mereka"],["قُوَّةًۭ ۖ","(dalam) kekuatan"],["وَكَانُوا۟","Tetapi mereka pernah"],["بِـَٔايَـٰتِنَا","dalam Tanda-tanda Kami"],["يَجْحَدُونَ","menafikan"]]],"4234":["(Maka Kami meniupkan angin yang amat gemuruh kepada mereka) yakni angin dingin yang sangat keras suaranya, tetapi tanpa hujan (dalam beberapa hari yang sial) dapat dibaca Nahisaatin atau Nahsaatin, artinya hari-hari yang penuh dengan kesialan bagi mereka (karena Kami hendak merasakan kepada mereka itu siksaan yang menghinakan) azab yang menghinakan (dalam kehidupan dunia. Dan sesungguhnya siksaan akhirat lebih menghinakan) lebih keras penghinaannya (sedangkan mereka tidak diberi pertolongan) yang dapat mencegah azab dari diri mereka.",[["فَأَرْسَلْنَا","Maka Kami hantarkan"],["عَلَيْهِمْ","ke atas mereka"],["رِيحًۭا","angin"],["صَرْصَرًۭا","geram"],["فِىٓ","dalam"],["أَيَّامٍۢ","(the) hari"],["نَّحِسَاتٍۢ","(dari) kemalangan"],["لِّنُذِيقَهُمْ","supaya Kami rasakan mereka"],["عَذَابَ","azab"],["ٱلْخِزْىِ","(dari) kehinaan"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["وَلَعَذَابُ","Dan sesungguhnya azab"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["أَخْزَىٰ ۖ","(adalah) lebih memalukan"],["وَهُمْ","dan mereka"],["لَا","tidak akan dibantu"],["يُنصَرُونَ","tidak akan dibantu"]]],"4235":["(Adapun Kaum Tsamud maka mereka telah Kami beri petunjuk) yaitu Kami telah menjelaskan kepada mereka jalan petunjuk (tetapi mereka lebih menyukai buta) artinya, lebih memilih kafir (daripada petunjuk itu, maka mereka disambar petir azab yang menghinakan) mereka dihinakan oleh azab berupa petir (disebabkan apa yang telah mereka kerjakan.)",[["وَأَمَّا","Dan untuk"],["ثَمُودُ","kaum Thamud"],["فَهَدَيْنَـٰهُمْ","Kami membimbing mereka"],["فَٱسْتَحَبُّوا۟","tetapi mereka lebih suka"],["ٱلْعَمَىٰ","[the] buta"],["عَلَى","atas"],["ٱلْهُدَىٰ","bimbingan"],["فَأَخَذَتْهُمْ","jadi merampas mereka"],["صَـٰعِقَةُ","petir"],["ٱلْعَذَابِ","(dari) hukuman itu"],["ٱلْهُونِ","memalukan"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَكْسِبُونَ","peroleh"]]],"4236":["(Dan Kami selamatkan) dari azab itu (orang-orang yang beriman dan mereka adalah orang-orang yang bertakwa.)",[["وَنَجَّيْنَا","Dan Kami selamatkan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَكَانُوا۟","dan pernah"],["يَتَّقُونَ","takut (Allah)"]]],"4237":["(Dan) ingatlah (hari ketika digiring) dapat dibaca Yuhsyaru atau Nahsyuru (musuh-musuh Allah ke dalam neraka lalu mereka dikumpulkan semuanya) yakni digiring semuanya ke dalam neraka.",[["وَيَوْمَ","Dan (hari) itu"],["يُحْشَرُ","akan dikumpulkan"],["أَعْدَآءُ","(para) musuh"],["ٱللَّهِ","(milik) Allah"],["إِلَى","kepada"],["ٱلنَّارِ","neraka"],["فَهُمْ","kemudian mereka"],["يُوزَعُونَ","akan dipasang dalam barisan"]]],"4238":["(Sehingga apabila) huruf Maa di sini adalah Zaidah atau tambahan (mereka sampai ke neraka, pendengaran, penglihatan dan kulit mereka menjadi saksi terhadap mereka tentang apa yang telah mereka kerjakan.)",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["مَا","apabila"],["جَآءُوهَا","mereka datang kepadanya"],["شَهِدَ","(akan) memberi keterangan"],["عَلَيْهِمْ","terhadap mereka"],["سَمْعُهُمْ","pendengaran mereka"],["وَأَبْصَـٰرُهُمْ","dan penglihatan mereka"],["وَجُلُودُهُم","dan kulit mereka"],["بِمَا","(as) kepada apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"4239":["(Dan mereka berkata kepada kulit mereka, \"Mengapa kalian menjadi saksi terhadap kami?\" Kulit mereka menjawab, \"Allah yang menjadikan segala sesuatu pandai berkata telah menjadikan kami pandai berkata) yakni segala sesuatu yang dikehendaki-Nya dapat berbicara (dan Dialah Yang menciptakan kalian pada kali yang pertama dan hanya kepada-Nyalah kalian dikembalikan\") menurut suatu pendapat, dikatakan bahwa perkataan ini adalah perkataan kulit. Menurut pendapat yang lain, perkataan ini adalah firman Allah swt. sebagaimana hal yang telah diterangkan sebelumnya, dan hal ini mirip sekali dengannya, yaitu: Bahwasanya Tuhan Yang mampu menciptakan kalian pada kali yang pertama, lalu menghidupkan kalian kembali sesudah mati, Dia mampu pula untuk menjadikan kulit kalian dan anggota tubuh kalian lainnya untuk dapat berbicara.",[["وَقَالُوا۟","Dan mereka akan berkata"],["لِجُلُودِهِمْ","kepada kulit mereka"],["لِمَ","kenapa buat"],["شَهِدتُّمْ","kamu bersaksi"],["عَلَيْنَا ۖ","terhadap kita"],["قَالُوٓا۟","Mereka akan berkata"],["أَنطَقَنَا","Allah menjadikan kita bercakap"],["ٱللَّهُ","Allah menjadikan kita bercakap"],["ٱلَّذِىٓ","yang Esa"],["أَنطَقَ","membuat bercakap"],["كُلَّ","setiap"],["شَىْءٍۢ","perkara"],["وَهُوَ","dan Dia"],["خَلَقَكُمْ","mencipta kamu"],["أَوَّلَ","(yang) pertama"],["مَرَّةٍۢ","masa"],["وَإِلَيْهِ","dan kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"4240":["(Dan kalian sekali-kali tidak dapat bersembunyi) bila kalian berbuat hal-hal yang keji (dari persaksian pendengaran, penglihatan dan kulit kalian terhadap kalian) karena sesungguhnya kalian tidak percaya dengan adanya hari berbangkit (bahkan kalian mengira) sewaktu kalian menyembunyikan diri (bahwa Allah tidak mengetahui kebanyakan dari apa yang kalian kerjakan.)",[["وَمَا","Dan tidak"],["كُنتُمْ","kamu dahulu"],["تَسْتَتِرُونَ","menutup diri"],["أَن","jangan-jangan"],["يَشْهَدَ","memberi keterangan"],["عَلَيْكُمْ","terhadap kamu"],["سَمْعُكُمْ","pendengaran kamu"],["وَلَآ","dan bukan"],["أَبْصَـٰرُكُمْ","penglihatan kamu"],["وَلَا","dan bukan"],["جُلُودُكُمْ","kulit kamu"],["وَلَـٰكِن","tetapi"],["ظَنَنتُمْ","kamu andaikan"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَعْلَمُ","mengetahui"],["كَثِيرًۭا","banyak"],["مِّمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"4241":["(Dan yang demikian itu) menjadi Mubtada (adalah prasangka kalian) menjadi Badal dari lafal Dzaalika (yang kalian sangka terhadap Rabb kalian) menjadi Na`at, sedangkan Khabar Mubtada ialah (akan menghancurkan kalian) akan membinasakan diri kalian sendiri (maka jadilah kalian termasuk orang-orang yang merugi.\")",[["وَذَٰلِكُمْ","Dan bahawa"],["ظَنُّكُمُ","(adalah) andaian kamu"],["ٱلَّذِى","yang"],["ظَنَنتُم","kamu andaikan"],["بِرَبِّكُمْ","tentang Tuhanmu"],["أَرْدَىٰكُمْ","Ia telah merosakkan kamu"],["فَأَصْبَحْتُم","dan kamu telah menjadi"],["مِّنَ","daripada"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"4242":["(Jika mereka bersabar) menderita azab (maka nerakalah tempat tinggal) tempat kediaman (bagi mereka, dan jika mereka mengemukakan alasan-alasan) maksudnya, jika mereka meminta kerelaan (maka tidaklah mereka termasuk orang-orang yang diterima alasannya) yakni orang-orang yang tidak mendapat kerelaan.",[["فَإِن","Kemudian jika"],["يَصْبِرُوا۟","mereka bertahan"],["فَٱلنَّارُ","neraka"],["مَثْوًۭى","(adalah) tempat tinggal"],["لَّهُمْ ۖ","bagi mereka"],["وَإِن","dan jika"],["يَسْتَعْتِبُوا۟","mereka meminta pertolongan"],["فَمَا","maka tidak"],["هُم","mereka"],["مِّنَ","(akan) daripada"],["ٱلْمُعْتَبِينَ","mereka yang mendapat nikmat"]]],"4243":["(Dan Kami tetapkan) Kami tentukan (bagi mereka teman-teman) dari kalangan setan-setan (yang menjadikan mereka memandang bagus apa yang ada di hadapan mereka) yaitu perkara duniawi dan memperturutkan nafsu syahwat (dan di belakang mereka) yaitu perkara akhirat, melalui perkataan mereka, bahwa tidak ada yang namanya hari berbangkit dan hari hisab itu (dan tetaplah atas mereka keputusan azab) sebagaimana yang telah diungkapkan oleh ayat yang lain, yaitu firman-Nya, \"Sesungguhnya Aku akan penuhi neraka Jahanam...\" (Q.S. As-Sajdah, 13) (pada) kalangan (umat-umat terdahulu) yang telah dibinasakan (sebelum mereka dari jin dan manusia, sesungguhnya mereka adalah orang- orang yang merugi.)",[["۞ وَقَيَّضْنَا","Dan telah Kami takdirkan"],["لَهُمْ","bagi mereka"],["قُرَنَآءَ","sahabat"],["فَزَيَّنُوا۟","(yang) membuat kelihatan adil"],["لَهُم","kepada mereka"],["مَّا","apa"],["بَيْنَ","(ada) sebelum mereka"],["أَيْدِيهِمْ","(ada) sebelum mereka"],["وَمَا","dan apa"],["خَلْفَهُمْ","(berada) di belakang mereka"],["وَحَقَّ","dan (adalah) wajar"],["عَلَيْهِمُ","terhadap mereka"],["ٱلْقَوْلُ","Firman"],["فِىٓ","antara"],["أُمَمٍۢ","bangsa-bangsa"],["قَدْ","(yang telah) meninggal dunia"],["خَلَتْ","(yang telah) meninggal dunia"],["مِن","sebelum mereka"],["قَبْلِهِم","sebelum mereka"],["مِّنَ","daripada"],["ٱلْجِنِّ","jin"],["وَٱلْإِنسِ ۖ","dan lelaki"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["خَـٰسِرِينَ","yang rugi"]]],"4244":["(Dan orang-orang yang kafir berkata) sewaktu Nabi saw. membaca Alquran, (\"Janganlah kalian mendengar bacaan Alquran ini dan buatlah hiruk-pikuk terhadapnya) yakni buatlah suara gaduh dan hiruk-pikuk untuk mengganggu bacaannya, dan mereka memang membuat hiruk-pikuk bilamana Nabi membaca Alquran (supaya kalian dapat mengalahkan\") bacaannya lalu ia menjadi diam tidak membaca Alquran.",[["وَقَالَ","Dan berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَا","Jangan"],["تَسْمَعُوا۟","dengar"],["لِهَـٰذَا","kepada ini"],["ٱلْقُرْءَانِ","Quran"],["وَٱلْغَوْا۟","dan buat bising"],["فِيهِ","di dalamnya"],["لَعَلَّكُمْ","supaya kamu"],["تَغْلِبُونَ","diatasi"]]],"4245":["Allah swt. berfirman mengisahkan tentang mereka, (Maka sesungguhnya Kami akan merasakan azab yang keras kepada orang-orang kafir dan Kami akan memberi balasan kepada mereka dengan seburuk-buruk pembalasan bagi apa yang telah mereka kerjakan) yakni pembalasan yang paling buruk sebagai imbalan dari perbuatan mereka itu.",[["فَلَنُذِيقَنَّ","Tetapi sesungguhnya Kami akan rasakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["عَذَابًۭا","azab"],["شَدِيدًۭا","teruk"],["وَلَنَجْزِيَنَّهُمْ","dan sesungguhnya Kami akan memberi balasan kepada mereka"],["أَسْوَأَ","(yang) paling teruk"],["ٱلَّذِى","apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"4246":["(Demikianlah) azab yang keras itu dan pembalasan yang paling buruk itu (balasan terhadap musuh-musuh Allah) dapat dibaca Jazaa-u A'daaillaahi atau Jazaa-uwa`daaillaahi, yaitu dapat dibaca Tahqiq dan Tas-hil (yaitu neraka) menjadi 'Athaf bayan dari lafal Jazaa-u dan berfungsi menjelaskan maknanya (mereka mendapat tempat tinggal yang kekal di dalamnya) tempat menetap yang tidak akan dipindahkan lagi daripadanya (sebagai pembalasan) dinashabkan karena menjadi Mashdar dari Fi'ilnya yang diperkirakan keberadaannya (dari sikap mereka terhadap ayat-ayat Kami) yakni Alquran (yang mereka ingkari.)",[["ذَٰلِكَ","Itu"],["جَزَآءُ","(ialah) balasan"],["أَعْدَآءِ","(daripada) musuh"],["ٱللَّهِ","(dari) Allah"],["ٱلنَّارُ ۖ","neraka"],["لَهُمْ","bagi mereka"],["فِيهَا","di dalamnya"],["دَارُ","(adalah) rumah"],["ٱلْخُلْدِ ۖ","(dari) keabadian"],["جَزَآءًۢ","(sebagai) balasan"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["بِـَٔايَـٰتِنَا","daripada Ayat-ayat Kami"],["يَجْحَدُونَ","menolak"]]],"4247":["(Dan orang-orang kafir berkata) sedang mereka di dalam neraka, (\"Ya Rabb kami! Perlihatkanlah kepada kami dua jenis makhluk yang telah menyesatkan kami yaitu sebagian dari jin dan manusia) yakni iblis dan Qabil yang keduanya adalah orang pertama yang mengerjakan kekafiran dan pembunuhan (agar kami letakkan keduanya di bawah telapak kaki kami) dalam neraka (supaya kedua jenis itu menjadi orang-orang yang paling bawah\") di neraka, artinya, azabnya lebih hebat daripada kami.",[["وَقَالَ","Dan (akan) berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["رَبَّنَآ","Wahai Tuhan kami"],["أَرِنَا","Tunjukkan kepada kami"],["ٱلَّذَيْنِ","orang yang"],["أَضَلَّانَا","menyesatkan kita"],["مِنَ","daripada"],["ٱلْجِنِّ","jin"],["وَٱلْإِنسِ","dan lelaki"],["نَجْعَلْهُمَا","(jadi) kami boleh meletakkan mereka"],["تَحْتَ","bawah"],["أَقْدَامِنَا","kaki kita"],["لِيَكُونَا","bahawa mereka menjadi"],["مِنَ","daripada"],["ٱلْأَسْفَلِينَ","paling rendah"]]],"4248":["(Sesungguhnya orang-orang yang mengatakan, \"Rabb kami adalah Allah,\" kemudian mereka meneguhkan pendirian mereka) dalam ajaran tauhid dan lain-lainnya yang diwajibkan atas mereka (maka malaikat akan turun kepada mereka) sewaktu mereka mati (\"Hendaknya kalian jangan merasa takut) akan mati dan hal-hal yang sesudahnya (dan jangan pula kalian merasa sedih) atas semua yang telah kalian tinggalkan, yaitu istri dan anak-anak, maka Kamilah yang akan menggantikan kedudukan mereka di sisi kalian (dan bergembiralah dengan surga yang telah dijanjikan Allah kepada kalian.)",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["قَالُوا۟","berkata"],["رَبُّنَا","Wahai Tuhan kami"],["ٱللَّهُ","(ialah) Allah"],["ثُمَّ","kemudian"],["ٱسْتَقَـٰمُوا۟","berdiri teguh"],["تَتَنَزَّلُ","akan turun"],["عَلَيْهِمُ","ke atas mereka"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["أَلَّا","Jangan"],["تَخَافُوا۟","bertakwa"],["وَلَا","dan jangan"],["تَحْزَنُوا۟","bersedih"],["وَأَبْشِرُوا۟","tetapi terimalah berita gembira itu"],["بِٱلْجَنَّةِ","daripada Syurga"],["ٱلَّتِى","yang"],["كُنتُمْ","kamu dahulu"],["تُوعَدُونَ","dijanjikan"]]],"4249":["(Kamilah pelindung-pelindung kalian dalam kehidupan dunia) artinya, Kami memelihara kalian di dalamnya (dan di akhirat) maksudnya, Kami akan selalu bersama kalian di akhirat hingga kalian masuk surga (di dalamnya kalian memperoleh apa yang kalian inginkan dan memperoleh pula di dalamnya apa yang kalian minta) berupa semua kenikmatan yang kalian minta.",[["نَحْنُ","Kami"],["أَوْلِيَآؤُكُمْ","(adalah) pelindung kamu"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَفِى","dan dalam"],["ٱلْـَٔاخِرَةِ ۖ","akhirat"],["وَلَكُمْ","Dan untuk kamu"],["فِيهَا","di dalamnya"],["مَا","apa sahaja"],["تَشْتَهِىٓ","keinginan"],["أَنفُسُكُمْ","jiwa kamu"],["وَلَكُمْ","dan untuk kamu"],["فِيهَا","di dalamnya"],["مَا","apa"],["تَدَّعُونَ","kamu tanya"]]],"4250":["(Sebagai hidangan) sebagai rezeki yang telah dipersiapkan bagi kalian; lafal ayat ini dinashabkan oleh lafal Ja'ala yang keberadaannya diperkirakan sebelumnya (dari Rabb Yang Maha Pengampun lagi Maha Penyayang\") yaitu dari Allah swt.",[["نُزُلًۭا","Hadiah mesra"],["مِّنْ","daripada"],["غَفُورٍۢ","(yang) Selalu Pemaaf"],["رَّحِيمٍۢ","(yang) Maha Penyayang"]]],"4251":["(Siapakah yang lebih baik perkataannya) maksudnya, tiada seorang pun yang lebih baik perkataannya (daripada seorang yang menyeru kepada Allah) yakni mentauhidkan-Nya (mengerjakan amal yang saleh dan berkata, \"Sesungguhnya aku termasuk orang-orang yang berserah diri?\")",[["وَمَنْ","Dan siapa"],["أَحْسَنُ","(lebih) baik"],["قَوْلًۭا","(dalam) ucapan"],["مِّمَّن","daripada (seorang) yang"],["دَعَآ","menjemput"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["وَعَمِلَ","dan melakukan"],["صَـٰلِحًۭا","benar (perbuatan)"],["وَقَالَ","dan berkata"],["إِنَّنِى","Memang aku"],["مِنَ","daripada"],["ٱلْمُسْلِمِينَ","mereka yang tunduk"]]],"4252":["(Dan tidaklah sama kebaikan dan kejahatan) dalam tingkatan rinciannya, karena sebagian daripada keduanya berada di atas sebagian yang lain. (Tolaklah) kejahatan itu (dengan cara) yakni dengan perbuatan (yang lebih baik) seperti marah, imbangilah dengan sabar, bodoh imbangilah dengan santunan, dan perbuatan jahat imbangilah dengan lapang dada atau pemaaf (maka tiba-tiba orang yang antaramu dan antara dia ada permusuhan seolah-olah menjadi teman yang setia) maka jadilah yang dulunya musuhmu kini menjadi teman sejawat dalam hal saling kasih mengasihi, jika kamu mempunyai sikap seperti tersebut. Lafal Al Ladzii Mubtada, dan Ka-annahu adalah Khabarnya, lafal Idzaa menjadi Zharaf bagi makna Tasybih.",[["وَلَا","Dan tidak"],["تَسْتَوِى","(adalah) sama"],["ٱلْحَسَنَةُ","kebaikan (perbuatan)"],["وَلَا","dan"],["ٱلسَّيِّئَةُ ۚ","kejahatan (perbuatan)"],["ٱدْفَعْ","Tolak"],["بِٱلَّتِى","oleh (itu) yang"],["هِىَ","[ia]"],["أَحْسَنُ","(lebih) baik"],["فَإِذَا","maka lihatlah"],["ٱلَّذِى","Seorang yang"],["بَيْنَكَ","antara kamu"],["وَبَيْنَهُۥ","dan antara dia"],["عَدَٰوَةٌۭ","(adalah) permusuhan"],["كَأَنَّهُۥ","(akan menjadi) seolah-olah dia"],["وَلِىٌّ","(adalah) kawan"],["حَمِيمٌۭ","intim"]]],"4253":["(Sifat-sifat yang baik itu tidak dianugerahkan) tidak akan diberikan (melainkan kepada orang-orang yang sabar dan tidak dianugerahkan melainkan kepada orang-orang yang mempunyai keberuntungan) yakni pahala (yang besar.)",[["وَمَا","Dan tidak"],["يُلَقَّىٰهَآ","ia diberikan"],["إِلَّا","kecuali"],["ٱلَّذِينَ","(kepada) mereka yang"],["صَبَرُوا۟","(adalah) sabar"],["وَمَا","dan bukan"],["يُلَقَّىٰهَآ","ia diberikan"],["إِلَّا","kecuali"],["ذُو","(kepada) pemilik"],["حَظٍّ","(dari) nasib"],["عَظِيمٍۢ","yang besar"]]],"4254":["(Dan jika) lafal Immaa ini pada asalnya terdiri dari In Syarthiyyah dan Maa Zaidah yang kemudian keduanya diidgamkan menjadi satu sehingga jadilah Immaa (setan mengganggumu dengan suatu gangguan) yakni jika setan mengalihkan perhatianmu dari pekerti yang baik kepada pekerti yang buruk (maka mohonlah perlindungan kepada Allah) lafal ayat ini menjadi Jawab Syarat, sedangkan Jawab Amar tidak disebutkan, yakni niscaya Dia akan menolak gangguan setan itu dalam dirimu. (Sesungguhnya Dialah Yang Maha Mendengar) semua percakapan (lagi Maha Mengetahui) semua perbuatan.",[["وَإِمَّا","Dan jika"],["يَنزَغَنَّكَ","bisikan datang kepada kamu"],["مِنَ","daripada"],["ٱلشَّيْطَـٰنِ","syaitan"],["نَزْغٌۭ","cadangan jahat"],["فَٱسْتَعِذْ","maka berlindunglah"],["بِٱللَّهِ ۖ","kepada Allah"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","[Dia]"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"4255":["(Dan sebagian dari tanda-tanda kekuasaan-Nya ialah malam, siang, matahari, dan bulan. Janganlah kalian bersujud kepada matahari dan jangan pula kepada bulan, tetapi bersujudlah kepada Allah Yang menciptakannya) yang telah menciptakan keempat tanda-tanda tersebut (jika kalian hanya kepada-Nya saja menyembah.)",[["وَمِنْ","Dan daripada"],["ءَايَـٰتِهِ","Tanda-tandaNya"],["ٱلَّيْلُ","(adalah) malam"],["وَٱلنَّهَارُ","dan hari"],["وَٱلشَّمْسُ","dan matahari"],["وَٱلْقَمَرُ ۚ","dan bulan"],["لَا","Jangan"],["تَسْجُدُوا۟","sujud"],["لِلشَّمْسِ","kepada matahari"],["وَلَا","dan bukan"],["لِلْقَمَرِ","ke bulan"],["وَٱسْجُدُوا۟","tapi sujud"],["لِلَّهِ","kepada Allah"],["ٱلَّذِى","yang Esa"],["خَلَقَهُنَّ","mencipta mereka"],["إِن","jika"],["كُنتُمْ","kamu"],["إِيَّاهُ","Dia sahaja"],["تَعْبُدُونَ","ibadah"]]],"4256":["(Jika mereka menyombongkan diri) tidak mau bersujud atau menyembah kepada Allah semata (maka mereka yang di sisi Rabbmu) yakni malaikat-malaikat (bertasbih) artinya, salat (kepada-Nya di malam dan siang hari, sedangkan mereka tidak jemu-jemu) tidak pernah merasa jemu bertasbih.",[["فَإِنِ","Tetapi jika"],["ٱسْتَكْبَرُوا۟","mereka sombong"],["فَٱلَّذِينَ","kemudian mereka yang"],["عِندَ","(ada) dekat"],["رَبِّكَ","Tuhanmu"],["يُسَبِّحُونَ","bertasbih"],["لَهُۥ","Dia"],["بِٱلَّيْلِ","pada waktu malam"],["وَٱلنَّهَارِ","dan hari"],["وَهُمْ","Dan mereka"],["لَا","jangan"],["يَسْـَٔمُونَ ۩","tayar"]]],"4257":["(Dan sebagian dari tanda-tanda kekuasaan-Nya bahwa kamu melihat bumi itu kering tandus) yaitu tidak ada tumbuh-tumbuhan padanya (maka apabila Kami turunkan air di atasnya, niscaya ia bergerak) berubah (dan subur) yakni menjadi subur dan rimbun penuh dengan tetumbuhan. (Sesungguhnya Tuhan Yang menghidupkannya tentu dapat menghidupkan yang mati; sesungguhnya Dia Maha Kuasa atas segala sesuatu.)",[["وَمِنْ","Dan antara"],["ءَايَـٰتِهِۦٓ","Tanda-tandaNya"],["أَنَّكَ","(ialah) kamu"],["تَرَى","lihat"],["ٱلْأَرْضَ","bumi"],["خَـٰشِعَةًۭ","mandul"],["فَإِذَآ","tapi apabila"],["أَنزَلْنَا","Kami hantar turun"],["عَلَيْهَا","atasnya"],["ٱلْمَآءَ","air"],["ٱهْتَزَّتْ","ia dikacau (untuk hidup)"],["وَرَبَتْ ۚ","dan berkembang"],["إِنَّ","Sesungguhnya"],["ٱلَّذِىٓ","yang Esa"],["أَحْيَاهَا","memberikannya kehidupan"],["لَمُحْىِ","(adalah) sesungguhnya yang memberi kehidupan"],["ٱلْمَوْتَىٰٓ ۚ","(kepada) orang mati"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌ","Maha Berkuasa"]]],"4258":["(Sesungguhnya orang-orang yang mengingkari) diambil dari kata Alhada dan Lahada artinya ingkar (kepada ayat-ayat Kami) yakni Alquran dengan cara mendustakannya (mereka tidak tersembunyi dari Kami) maka pasti Kami akan membalas mereka. (Maka apakah orang-orang yang dilemparkan ke dalam neraka lebih baik ataukah orang-orang yang datang dengan aman sentosa pada hari kiamat? Perbuatlah apa yang kalian kehendaki; sesungguhnya Dia Maha Mengetahui apa yang kalian kerjakan) ayat ini merupakan ancaman bagi mereka.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُلْحِدُونَ","memutarbelitkan"],["فِىٓ","[dalam]"],["ءَايَـٰتِنَا","Ayat Kami"],["لَا","(adalah) tidak"],["يَخْفَوْنَ","tersembunyi"],["عَلَيْنَآ ۗ","daripada Kami"],["أَفَمَن","Jadi, adakah (dia) yang"],["يُلْقَىٰ","dibuang"],["فِى","dalam"],["ٱلنَّارِ","neraka"],["خَيْرٌ","lebih baik"],["أَم","atau"],["مَّن","(dia) siapa"],["يَأْتِىٓ","datang"],["ءَامِنًۭا","selamat"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۚ","(dari) Kebangkitan"],["ٱعْمَلُوا۟","buat"],["مَا","apa"],["شِئْتُمْ ۖ","kamu akan"],["إِنَّهُۥ","Sesungguhnya Dia"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌ","(ialah) Maha Melihat"]]],"4259":["(Sesungguhnya orang-orang yang mengingkari peringatan) Alquran (ketika ia datang kepada mereka) niscaya Kami akan membalas mereka (dan sesungguhnya Alquran itu adalah kitab yang mulia) artinya, perkasa.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["بِٱلذِّكْرِ","dalam Peringatan"],["لَمَّا","apabila"],["جَآءَهُمْ ۖ","ia datang kepada mereka"],["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["لَكِتَـٰبٌ","(adalah) sesungguhnya sebuah Kitab"],["عَزِيزٌۭ","perkasa"]]],"4260":["(Yang tidak datang kepadanya Alquran kebatilan baik dari depan maupun dari belakangnya) yakni tidak ada suatu kitab pun sebelumnya yang mendustakannya, dan tidak pula sesudahnya (yang diturunkan dari Tuhan Yang Maha Bijaksana lagi Maha Terpuji) Allah Yang Maha Terpuji di dalam semua urusan-Nya.",[["لَّا","Tidak"],["يَأْتِيهِ","datang kepadanya"],["ٱلْبَـٰطِلُ","kepalsuan itu"],["مِنۢ","daripada"],["بَيْنِ","sebelum itu"],["يَدَيْهِ","sebelum itu"],["وَلَا","dan bukan"],["مِنْ","daripada"],["خَلْفِهِۦ ۖ","di belakangnya"],["تَنزِيلٌۭ","Sebuah Wahyu"],["مِّنْ","daripada"],["حَكِيمٍ","(yang) Maha Bijaksana"],["حَمِيدٍۢ","(yang) Terpuji"]]],"4261":["(Tidaklah ada yang dikatakan kepadamu itu) yakni kedustaan (kecuali) sebagaimana (apa yang sesungguhnya telah dikatakan kepada rasul-rasul sebelum kamu. Sesungguhnya Rabbmu benar-benar mempunyai ampunan) buat orang-orang yang beriman (dan hukuman yang pedih) bagi orang-orang kafir.",[["مَّا","Tidak"],["يُقَالُ","dikatakan"],["لَكَ","kepada kamu"],["إِلَّا","kecuali"],["مَا","apa"],["قَدْ","telah dikatakan"],["قِيلَ","telah dikatakan"],["لِلرُّسُلِ","kepada para Rasul"],["مِن","sebelum kamu"],["قَبْلِكَ ۚ","sebelum kamu"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لَذُو","(ialah) Pemilik"],["مَغْفِرَةٍۢ","(dari) pengampunan"],["وَذُو","dan Pemilik"],["عِقَابٍ","(dari) penalti"],["أَلِيمٍۢ","yang pedih"]]],"4262":["(Dan jika Kami jadikan ia) yakni Alquran itu (suatu bacaan dalam bahasa selain bahasa Arab tentu mereka mengatakan, \"Mengapa tidak) kenapa tidak (dijelaskan) diterangkan (ayat-ayatnya?) sehingga kami dapat memahaminya. (Apakah) patut Alquran (dalam bahasa asing sedangkan) nabi (adalah orang Arab) Istifham atau kata tanya di sini mengandung makna ingkar, yakni menunjukkan keingkaran mereka. Dan lafal A'jamiyyun ini dapat dibaca Tahqiq dan dapat pula dibaca Tas-hil. (Katakanlah, \"Alquran ini bagi orang-orang yang beriman adalah petunjuk) dari kesesatan (dan penawar) dari kebodohan. (Dan orang-orang yang tidak beriman pada telinga mereka ada sumbatan) penutup, sehingga mereka tidak dapat mendengar (sedangkan Alquran itu suatu kegelapan bagi mereka) karena itu mereka tidak dapat memahaminya. (Mereka itu adalah seperti orang-orang yang dipanggil dari tempat yang jauh\") karenanya mereka tidak dapat mendengar dan tidak dapat memahami panggilan yang ditujukan kepadanya.",[["وَلَوْ","Dan jika"],["جَعَلْنَـٰهُ","Kami (telah) berjaya"],["قُرْءَانًا","sebuah Al-Quran"],["أَعْجَمِيًّۭا","(dalam) asing (bahasa)"],["لَّقَالُوا۟","mereka (akan) berkata"],["لَوْلَا","kenapa tidak"],["فُصِّلَتْ","dijelaskan secara terperinci"],["ءَايَـٰتُهُۥٓ ۖ","ayat-ayatnya"],["ءَا۬عْجَمِىٌّۭ","(Adakah ia) asing (bahasa)"],["وَعَرَبِىٌّۭ ۗ","dan seorang Arab"],["قُلْ","Katakanlah"],["هُوَ","Ia (adalah)"],["لِلَّذِينَ","bagi mereka yang"],["ءَامَنُوا۟","beriman"],["هُدًۭى","sebuah petunjuk"],["وَشِفَآءٌۭ ۖ","dan kesembuhan"],["وَٱلَّذِينَ","Dan orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["فِىٓ","dalam"],["ءَاذَانِهِمْ","telinga mereka"],["وَقْرٌۭ","(adalah) pekak"],["وَهُوَ","dan ia"],["عَلَيْهِمْ","(adalah) untuk mereka"],["عَمًى ۚ","buta"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["يُنَادَوْنَ","sedang dipanggil"],["مِن","daripada"],["مَّكَانٍۭ","sebuah tempat"],["بَعِيدٍۢ","jauh"]]],"4263":["(Dan sesungguhnya telah Kami berikan kepada Musa Kitab) yakni Taurat (lalu diperselisihkan tentang Taurat itu) ada yang mempercayainya dan ada pula yang mendustakannya, sama dengan apa yang dialami oleh Alquran. (Kalau tidak ada keputusan yang telah terdahulu dari Rabbmu) yang telah memutuskan untuk menangguhkan hisab dan pembalasan bagi semua makhluk sampai hari kiamat nanti (tentulah telah diputuskan di antara mereka) di dunia ini tentang apa yang mereka perselisihkan itu. (Dan sesungguhnya mereka) yaitu orang-orang yang mendustakan terhadap Alquran (benar-benar dalam keragu-raguan yang membingungkan terhadap Alquran) mereka benar-benar ragu terhadapnya.",[["وَلَقَدْ","Dan sungguh"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","Kitab"],["فَٱخْتُلِفَ","tetapi pertikaian timbul"],["فِيهِ ۗ","di dalamnya"],["وَلَوْلَا","Dan sekiranya ia tidak berlaku"],["كَلِمَةٌۭ","(untuk) perkataan"],["سَبَقَتْ","(yang) mendahului"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["لَقُضِىَ","pasti, akan diselesaikan"],["بَيْنَهُمْ ۚ","antara mereka"],["وَإِنَّهُمْ","Tetapi sesungguhnya, mereka"],["لَفِى","pasti (berada) dalam"],["شَكٍّۢ","keraguan"],["مِّنْهُ","mengenainya"],["مُرِيبٍۢ","meresahkan"]]],"4264":["(Barang siapa yang mengerjakan amal yang saleh maka pahalanya untuk dirinya sendiri) ia beramal untuk dirinya sendiri (dan barang siapa yang berbuat jahat maka dosanya atas dirinya sendiri) bahaya dari perbuatan jahatnya itu kembali kepada dirinya sendiri (dan sekali-kali tidaklah Rabbmu menganiaya hamba-hamba-Nya) Dia bukanlah penganiaya hamba-hamba-Nya sebagaimana yang telah diungkapkan oleh ayat lainnya, yaitu firman-Nya, \"Sesungguhnya Allah tidak menganiaya seorang pun walaupun sebesar dzarrah.\" (Q.S. An-Nisa, 40)",[["مَّنْ","Siapa pun"],["عَمِلَ","tidak"],["صَـٰلِحًۭا","amal soleh"],["فَلِنَفْسِهِۦ ۖ","maka ia adalah untuk jiwanya"],["وَمَنْ","dan sesiapa"],["أَسَآءَ","melakukan kejahatan"],["فَعَلَيْهَا ۗ","maka ia menentangnya"],["وَمَا","Dan tidak"],["رَبُّكَ","(ialah) Tuhanmu"],["بِظَلَّـٰمٍۢ","tidak adil"],["لِّلْعَبِيدِ","kepada hamba-hamba-Nya"]]]});